-- [kmarket_ecommerce.brand_vendor_contracts] 입점 브랜드 계약 및 판촉비 분담 약정 테이블 (8건)
CREATE OR REPLACE TABLE `YOUR_PROJECT_ID.kmarket_ecommerce.brand_vendor_contracts` AS
SELECT * FROM UNNEST([
  STRUCT('BRD-01' AS brand_id, '아틀리에누아르' AS brand_name, '특약매입' AS trade_type, 28.0 AS base_commission_pct, 60.0 AS agreed_promo_share_pct, 'Y' AS written_promo_agreement_yn, 24 AS sla_ship_hours),
