-- [kmarket_ontology.ctx_business_contexts] 6대 부서/업무목적 비즈니스 맥락 (CTX Layer)
CREATE OR REPLACE TABLE `YOUR_PROJECT_ID.kmarket_ontology.ctx_business_contexts` AS
SELECT * FROM UNNEST([
  STRUCT('CRM_GROWTH' AS context_id, '그로스마케팅본부·AI추천랩' AS dept_name, '장바구니 이탈 실시간 탐지, 개인정보 마케팅 동의 검증, 코디 번들·대체상품 추천 및 등급별 타겟팅 쿠폰 발급' AS purpose_summary, '장바구니 미결제 세션(event_type=\'cart\'), 마케팅 동의(marketing_opt_in=True), VVIP/VIP 최대 15% 번들 쿠폰' AS primary_metric_scope),
  STRUCT('MD_MERCHANDISING', 'MD본부·가격전략실', '상시 프로모션 최저 실현마진율(25%) 가드레일 통제 및 90일 이상 체화재고 클리어런스(10% 하한 완화) 승인', '실현마진율((sale_price_krw - cost_krw)/sale_price_krw >= 25%), 체화재고(stock_age_days >= 90) 10% 마진 완화'),
  STRUCT('PARTNER_SETTLEMENT', '파트너상생본부·정산실', '입점브랜드 공동프로모션 사전 서면약정 확인 및 대규모유통업법 제11조 납품업자 판촉비 분담비율 50% 상한 캡 정산', '사전약정(signed_promo_agreement=True), 브랜드 분담률 캡 MIN(promo_cost_share_ratio, 0.50), 초과분 K마켙 흡수'),
  STRUCT('CX_CS_SUPPORT', '고객경험(CX)본부·CS심사팀', '반품 사유별 청약철회 가능 기한(단순변심 7일 vs 표시·광고 상이 90일) 판정, 반품배송비 귀속 및 3영업일 환불 관리', 'CHANGE_OF_MIND(7일/6,000원 고객부담), SIZE_MISMATCH_SPEC_DIFF(90일/무상반품), WEAR_AND_WASH_DAMAGE(청약철회 거절)'),
  STRUCT('FULFILLMENT_OPS', '풀필먼트운영실', '김포·용인·양산 물류센터별 실시간 가용재고 관리 및 약속 출고 SLA(24h/36h/48h) 초과 시 지연보상 3,000P 지급', '가용재고(available_stock), 물류센터별 출고 SLA(김포 24h·용인 36h·양산 48h) 위반 감지 및 3,000P 자동 보상'),
  STRUCT('LEGAL_COMPLIANCE', '준법감시실·개인정보보호팀', '대규모유통업법·전자상거래법·개보위 행태정보 가이드라인 준수 감리 및 자발적 판촉행사 신청·다크패턴 적격성 심사', '비동의 회원(marketing_opt_in=False) 타겟팅 차단, 상시 캠페인 자발성 예외 신청 기각(REJECTED), 해외직구 고시 혼동 방지')
]);

-- [kmarket_ontology.lex_source_documents] 10대 법령·심사지침·사내내규·대조군 문서 루트 (LEX Layer)
