  STRUCT('DOC_02_FTC_PROMO_GUIDE', '02', '대규모유통업 분야 판매촉진비용 부담전가 행위에 대한 위법성 심사지침 (공정위 예규 제445호)', 'binding', 'DOMESTIC_ECOMMERCE', '공정거래위원회', 'regulations/02_ftc_promo_cost_guideline/doc', 'gs://kmarket_okf/okf/regulations/02_ftc_promo_cost_guideline/doc.md'),
