  STRUCT('DOC_04_FTC_DARK_PATTERN', '04', '온라인 다크패턴(눈속임 상술) 자율관리 가이드라인 및 맞춤형 추천 투명성 지침', 'advisory', 'DOMESTIC_ECOMMERCE', '공정거래위원회', 'regulations/04_ftc_dark_pattern_and_reco_guideline/doc', 'gs://kmarket_okf/okf/regulations/04_ftc_dark_pattern_and_reco_guideline/doc.md'),
  STRUCT('DOC_05_PIPC_BEHAVIORAL', '05', '온라인 맞춤형 광고 개인정보보호 가이드라인 및 전자상거래 행태정보 처리 기준', 'advisory', 'DOMESTIC_ECOMMERCE', '개인정보보호위원회', 'regulations/05_pipc_behavioral_targeting_guideline/doc', 'gs://kmarket_okf/okf/regulations/05_pipc_behavioral_targeting_guideline/doc.md'),
  STRUCT('DOC_06_DISTRACTOR_CUSTOMS', '06', '[Distractor] 목록통관 및 특송물품 수입통관 사무처리에 관한 고시 (관세청 고시 제2025-12호)', 'distractor', 'OVERSEAS_DIRECT_CUSTOMS', '관세청', 'distractors/06_distractor_customs_overseas_direct/doc', 'gs://kmarket_okf/okf/distractors/06_distractor_customs_overseas_direct/doc.md'),
  STRUCT('DOC_07_KMARKET_CRM_POLICY', '07', 'K마켙 초개인화 추천 알고리즘 및 CRM 타겟팅 쿠폰 운영내규 (제CRM-2025-01호)', 'internal', 'DOMESTIC_ECOMMERCE', '주식회사 K마켙 그로스마케팅본부', 'internal_policies/07_kmarket_crm_hyper_personalization/doc', 'gs://kmarket_okf/okf/internal_policies/07_kmarket_crm_hyper_personalization/doc.md'),
  STRUCT('DOC_08_KMARKET_MD_POLICY', '08', 'K마켙 MD 상품마진 가드레일 및 체화재고 클리어런스 가격결정 내규 (제MD-2025-02호)', 'internal', 'DOMESTIC_ECOMMERCE', '주식회사 K마켙 MD본부', 'internal_policies/08_kmarket_md_margin_and_clearance/doc', 'gs://kmarket_okf/okf/internal_policies/08_kmarket_md_margin_and_clearance/doc.md'),
  STRUCT('DOC_09_KMARKET_PARTNER_POLICY', '09', 'K마켙 입점브랜드 공동프로모션 및 쿠폰분담금 정산내규 (제PARTNER-2025-03호)', 'internal', 'DOMESTIC_ECOMMERCE', '주식회사 K마켙 파트너상생본부', 'internal_policies/09_kmarket_vendor_promo_settlement/doc', 'gs://kmarket_okf/okf/internal_policies/09_kmarket_vendor_promo_settlement/doc.md'),
