-- [kmarket_ontology.lex_provisions] 36개 조문·심사기준·사내내규 슬롯 및 원문 (LEX Layer)
CREATE OR REPLACE TABLE `YOUR_PROJECT_ID.kmarket_ontology.lex_provisions` AS
SELECT * FROM UNNEST([
  STRUCT('regulations/01_law_large_retail_fair_trade/ch01_general_and_contract/art_001_002_purpose_definitions' AS provision_slot_id, 'DOC_01_LAW_LARGE_RETAIL' AS doc_id, 'regulations/01_law_large_retail_fair_trade/ch01_general_and_contract/art_001_002_purpose_definitions' AS kc_entry_id, '제1조~제2조' AS article_no, '제1조(목적) 및 제2조(정의 — 대규모유통업자·납품업자·직매입·특약매입·위수탁)' AS title, 'BASE_CRITERIA' AS provision_role, 'ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio,ont_orders.delivered_at,ont_orders.return_requested_at' AS target_columns, CAST(NULL AS STRING) AS missing_schema_columns, 'gs://kmarket_okf/okf/regulations/01_law_large_retail_fair_trade/ch01_general_and_contract/art_001_002_purpose_definitions.md' AS gcs_uri, '# 제1조(목적) 및 제2조(정의 — 대규모유통업자·납품업자·직매입·특약매입·위수탁)\n\n* **상위 문서 (`Source Document`)**: [대규모유통업에서의 거래공정화에 관한 법률 (법률 제20195호, 2025. 1. 1. 시행)](/regulations/01_law_large_retail_fair_trade/doc.md)[^origin_pdf]\n* **출처 페이지**: `01_LAW_대규모유통업법_전문_2025.pdf` — **1쪽** (`section_number: 제1조~제2조`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n제1조(목적) 이 법은 대규모유통업에서의 공정한 거래질서를 확립하고 대규모유통업자와\n납품업자 또는 매장임차인이 대등한 지위에서 상호 보완하며 균형 있게 발전하도록 함으로써\n국민경제의 건전한 발전에 이바지함을 목적으로 한다.\n제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다.\n1. "대규모유통업자"란 소비자가 사용하는 상품을 다수의 사업자로부터 납품받아 판매하는\n사업자로서 직전 사업연도의 소매업종 매출액이 1천억원 이상이거나 매장면적의 합계가\n3천제곱미터 이상인 사업자(온라인쇼핑몰 운영 사업자를 포함한다)를 말한다.\n2. "납품업자"란 대규모유통업자에게 판매할 상품을 공급하는 사업자(입점브랜드 및\n벤더사를 포함한다)를 말한다.\n3. "직매입거래"란 대규모유통업자가 납품업자로부터 상품을 직접 매입하여 자기 책임하에\n판매하고 미판매 상품에 대한 재고 부담을 대규모유통업자가 지는 거래형태를 말한다.\n4. "특약매입거래"란 대규모유통업자가 매입한 상품 중 판매되지 아니한 상품을 반품할\n수 있는 조건으로 납품업자로부터 상품을 외상 매입하고 상품판매 후 일정률이나 일정액의\n판매수익을 공제한 상품판매대금을 납품업자에게 지급하는 거래형태를 말한다.\n5. "위수탁거래"란 대규모유통업자가 납품업자가 공급한 상품을 자기 명의로 판매하고\n수수료를 공제한 판매대금을 납품업자에게 지급하는 거래형태를 말한다.' AS full_text),
  STRUCT('regulations/01_law_large_retail_fair_trade/ch01_general_and_contract/art_006_written_contract', 'DOC_01_LAW_LARGE_RETAIL', 'regulations/01_law_large_retail_fair_trade/ch01_general_and_contract/art_006_written_contract', '제6조', '제6조(서면의 즉시 교부 및 계약사항 명시)', 'BASE_CRITERIA', 'ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio,ont_orders.delivered_at,ont_orders.return_requested_at', CAST(NULL AS STRING), 'gs://kmarket_okf/okf/regulations/01_law_large_retail_fair_trade/ch01_general_and_contract/art_006_written_contract.md', '# 제6조(서면의 즉시 교부 및 계약사항 명시)\n\n* **상위 문서 (`Source Document`)**: [대규모유통업에서의 거래공정화에 관한 법률 (법률 제20195호, 2025. 1. 1. 시행)](/regulations/01_law_large_retail_fair_trade/doc.md)[^origin_pdf]\n* **출처 페이지**: `01_LAW_대규모유통업법_전문_2025.pdf` — **1쪽** (`section_number: 제6조`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n제6조(서면의 즉시 교부 및 계약사항 명시) ① 대규모유통업자는 납품업자등과 계약을\n체결한 즉시 거래형태, 거래품목, 납품대금 지급기일, 판매수수료율 또는 마진율, 반품\n조건, 판매촉진비용 분담 기준 등이 명시된 서면(전자문서를 포함한다)을 납품업자등에게\n주어야 한다.\n② 대규모유통업자가 서면을 교부하지 아니하고 진행한 판촉행사 또는 단가 인하 약정은\n효력을 주장할 수 없으며 납품업자에게 불리하게 해석되어서는 아니 된다.\n\n대규모유통업에서의 거래공정화에 관한 법률 (발췌·전문) ― Page 1 / 4'),
  STRUCT('regulations/01_law_large_retail_fair_trade/ch02_payment_and_return_ban/art_008_payment_deadline', 'DOC_01_LAW_LARGE_RETAIL', 'regulations/01_law_large_retail_fair_trade/ch02_payment_and_return_ban/art_008_payment_deadline', '제8조', '제8조(납품대금의 지급 — 직매입 60일·특약매입 40일 및 지연이자 연 15.5%)', 'BASE_CRITERIA', 'ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio,ont_orders.delivered_at,ont_orders.return_requested_at', 'orders.monthly_closing_date,orders.vendor_payout_paid_at', 'gs://kmarket_okf/okf/regulations/01_law_large_retail_fair_trade/ch02_payment_and_return_ban/art_008_payment_deadline.md', '# 제8조(납품대금의 지급 — 직매입 60일·특약매입 40일 및 지연이자 연 15.5%)\n\n* **상위 문서 (`Source Document`)**: [대규모유통업에서의 거래공정화에 관한 법률 (법률 제20195호, 2025. 1. 1. 시행)](/regulations/01_law_large_retail_fair_trade/doc.md)[^origin_pdf]\n* **출처 페이지**: `01_LAW_대규모유통업법_전문_2025.pdf` — **2쪽** (`section_number: 제8조`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n제8조(납품대금의 지급) ① 대규모유통업자는 직매입거래의 경우 상품 수령일로부터 60일\n이내에, 특약매입거래·위수탁거래·매장임대차거래의 경우 월 판매마감일로부터 40일 이내에\n납품업자등에게 상품판매대금을 지급하여야 한다.\n② 대규모유통업자가 제1항에 따른 기한이 지난 후에 상품판매대금을 지급하는 경우에는 그\n초과기간에 대하여 공정거래위원회가 고시하는 지연이율(연 15.5퍼센트)에 따른\n지연이자를 지급하여야 한다.'),
  STRUCT('regulations/01_law_large_retail_fair_trade/ch02_payment_and_return_ban/art_010_unfair_return_ban', 'DOC_01_LAW_LARGE_RETAIL', 'regulations/01_law_large_retail_fair_trade/ch02_payment_and_return_ban/art_010_unfair_return_ban', '제10조', '제10조(상품의 반품 금지 및 특약매입·직매입 시즌상품 예외)', 'BASE_CRITERIA', 'ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio,ont_orders.delivered_at,ont_orders.return_requested_at', CAST(NULL AS STRING), 'gs://kmarket_okf/okf/regulations/01_law_large_retail_fair_trade/ch02_payment_and_return_ban/art_010_unfair_return_ban.md', '# 제10조(상품의 반품 금지 및 특약매입·직매입 시즌상품 예외)\n\n* **상위 문서 (`Source Document`)**: [대규모유통업에서의 거래공정화에 관한 법률 (법률 제20195호, 2025. 1. 1. 시행)](/regulations/01_law_large_retail_fair_trade/doc.md)[^origin_pdf]\n* **출처 페이지**: `01_LAW_대규모유통업법_전문_2025.pdf` — **2쪽** (`section_number: 제10조`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n제10조(상품의 반품 금지) ① 대규모유통업자는 정당한 사유 없이 납품받은 상품의 전부\n또는 일부를 반품하여서는 아니 된다. 다만, 다음 각 호의 어느 하나에 해당하는\n경우로서 거래관행상 정당하다고 인정되는 경우에는 그러하지 아니하다.\n1. 특약매입거래의 경우로서 계약체결 시 반품조건을 구체적으로 약정한 경우\n2. 직매입거래의 경우로서 납품업자의 책임 있는 사유로 인하여 상품이 오손·훼손되었거나\n결함이 있는 경우\n3. 직매입거래의 경우로서 납품받은 상품이 계약한 상품과 다른 경우\n4. 직매입거래의 경우로서 시즌상품(일정한 기간이나 계절에 집중적으로 판매되는\n패션·의류 등의 상품)에 대하여 계약체결 시 반품조건을 구체적으로 약정한 경우\n5. 납품업자가 자기의 이익을 위하여 자발적으로 서면으로 반품을 요청하고 객관적인\n증빙자료를 제출한 경우\n\n대규모유통업에서의 거래공정화에 관한 법률 (발췌·전문) ― Page 2 / 4'),
  STRUCT('regulations/01_law_large_retail_fair_trade/ch03_promo_cost_sharing_cap/art_011_p1_p2_prior_written_agreement', 'DOC_01_LAW_LARGE_RETAIL', 'regulations/01_law_large_retail_fair_trade/ch03_promo_cost_sharing_cap/art_011_p1_p2_prior_written_agreement', '제11조제1항~제2항', '제11조제1항·제2항(판매촉진비용 사전 서면약정 의무 및 5대 필수 기재사항)', 'BASE_CRITERIA', 'ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio,ont_orders.delivered_at,ont_orders.return_requested_at', CAST(NULL AS STRING), 'gs://kmarket_okf/okf/regulations/01_law_large_retail_fair_trade/ch03_promo_cost_sharing_cap/art_011_p1_p2_prior_written_agreement.md', '# 제11조제1항·제2항(판매촉진비용 사전 서면약정 의무 및 5대 필수 기재사항)\n\n* **상위 문서 (`Source Document`)**: [대규모유통업에서의 거래공정화에 관한 법률 (법률 제20195호, 2025. 1. 1. 시행)](/regulations/01_law_large_retail_fair_trade/doc.md)[^origin_pdf]\n* **출처 페이지**: `01_LAW_대규모유통업법_전문_2025.pdf` — **3쪽** (`section_number: 제11조제1항~제2항`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n제11조(판매촉진비용의 부담전가 금지) ① 대규모유통업자는 판매촉진행사를 실시하기\n이전에 대통령령으로 정하는 바에 따라 판매촉진행사에 소요되는 비용(이하\n"판매촉진비용"이라 한다. 할인쿠폰 발행비용, 가격할인 차액보전금, 사은품 비용,\n광고선전비를 포함한다)의 부담 등을 납품업자등과 약정하지 아니하고는 이를 납품업자등에게\n부담시키는 행위를 하여서는 아니 된다.\n② 제1항에 따른 약정은 대규모유통업자와 납품업자등이 각각 서명 또는 기명날인한\n서면으로 이루어져야 하며, 약정서에는 다음 각 호의 사항이 반드시 포함되어야 한다.\n1. 판매촉진행사의 명칭·성격 및 실시 기간\n2. 판매촉진행사를 통하여 판매할 상품의 품목 및 목표 수량\n3. 판매촉진행사에 소요될 것으로 예상되는 비용의 규모 및 산출 근거\n4. 해당 판매촉진행사로 인하여 대규모유통업자와 납품업자등이 직접적으로 얻을 것으로\n예상되는 경제적 이익(이하 "예상편익"이라 한다)의 비율\n5. 판매촉진비용의 분담비율 또는 분담액'),
  STRUCT('regulations/01_law_large_retail_fair_trade/ch03_promo_cost_sharing_cap/art_011_p3_p5_fifty_percent_cap_and_proviso', 'DOC_01_LAW_LARGE_RETAIL', 'regulations/01_law_large_retail_fair_trade/ch03_promo_cost_sharing_cap/art_011_p3_p5_fifty_percent_cap_and_proviso', '제11조제3항~제5항', '제11조제3항~제5항(납품업자 판촉비 분담비율 50% 상한 강행규정 및 자발적·차별화 행사 단서)', 'EXCEPTION_PROVISO', 'ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio,ont_orders.delivered_at,ont_orders.return_requested_at', CAST(NULL AS STRING), 'gs://kmarket_okf/okf/regulations/01_law_large_retail_fair_trade/ch03_promo_cost_sharing_cap/art_011_p3_p5_fifty_percent_cap_and_proviso.md', '# 제11조제3항~제5항(납품업자 판촉비 분담비율 50% 상한 강행규정 및 자발적·차별화 행사 단서)\n\n* **상위 문서 (`Source Document`)**: [대규모유통업에서의 거래공정화에 관한 법률 (법률 제20195호, 2025. 1. 1. 시행)](/regulations/01_law_large_retail_fair_trade/doc.md)[^origin_pdf]\n* **출처 페이지**: `01_LAW_대규모유통업법_전문_2025.pdf` — **3쪽** (`section_number: 제11조제3항~제5항`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n③ 제1항 및 제2항에 따른 판매촉진비용의 분담비율은 대규모유통업자와 납품업자등이 해당\n판매촉진행사를 통하여 직접적으로 얻을 것으로 예상되는 경제적 이익의 비율에 따라\n정하되, 대규모유통업자와 납품업자등 사이의 구체적인 분담비율을 산정할 수 없는 경우에는\n대규모유통업자와 납품업자등의 예상편익이 같은 것으로 추정한다.\n④ 제3항에 따른 납품업자등의 판매촉진비용 분담비율은 어떠한 경우에도 100분의 50을\n초과하여서는 아니 된다. 기본 거래계약서나 개별 특약에 100분의 50을 초과하는\n분담비율이 기재되어 있더라도 100분의 50을 초과하는 부분은 무효로 하며\n대규모유통업자가 전액 부담하여야 한다.\n⑤ 다만, 납품업자등이 자발적으로 대규모유통업자에게 요청하여 다른 납품업자등과\n차별화되는 판매촉진행사를 실시하려는 경우에는 대규모유통업자는 납품업자등과 상호 협의하여\n판매촉진비용의 분담비율을 정할 수 있다. 이 경우 제1항부터 제4항까지의 규정은\n적용하지 아니한다.\n\n대규모유통업에서의 거래공정화에 관한 법률 (발췌·전문) ― Page 3 / 4'),
  STRUCT('regulations/01_law_large_retail_fair_trade/ch04_exclusivity_and_record_keeping/art_012_017_018_fair_trade_duties', 'DOC_01_LAW_LARGE_RETAIL', 'regulations/01_law_large_retail_fair_trade/ch04_exclusivity_and_record_keeping/art_012_017_018_fair_trade_duties', '제12조·제17조·제18조', '제12조(배타적 거래 강요 금지)·제17조(경영정보 요구 금지)·제18조(서면 5년 보존의무)', 'BASE_CRITERIA', 'ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio,ont_orders.delivered_at,ont_orders.return_requested_at', CAST(NULL AS STRING), 'gs://kmarket_okf/okf/regulations/01_law_large_retail_fair_trade/ch04_exclusivity_and_record_keeping/art_012_017_018_fair_trade_duties.md', '# 제12조(배타적 거래 강요 금지)·제17조(경영정보 요구 금지)·제18조(서면 5년 보존의무)\n\n* **상위 문서 (`Source Document`)**: [대규모유통업에서의 거래공정화에 관한 법률 (법률 제20195호, 2025. 1. 1. 시행)](/regulations/01_law_large_retail_fair_trade/doc.md)[^origin_pdf]\n* **출처 페이지**: `01_LAW_대규모유통업법_전문_2025.pdf` — **4쪽** (`section_number: 제12조·제17조·제18조`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n제12조(배타적 거래 강요 금지) 대규모유통업자는 부당하게 납품업자등에게 경쟁\n온라인쇼핑몰이나 타 유통채널과 거래하지 못하게 하거나 타 채널 판매가격을 인상하도록\n강요하여서는 아니 된다.\n제17조(부당한 경영정보 요구 금지) 대규모유통업자는 정당한 사유 없이 납품업자등에게\n타 유통업자에 대한 공급조건, 원가내역, 입점현황 등 경영정보의 제공을 요구하여서는\n아니 된다.\n제18조(서면의 보존의무) 대규모유통업자는 제6조의 계약서면, 제10조의 반품 약정 및\n증빙서면, 제11조의 판매촉진비용 사전 약정서 및 정산내역서를 거래가 끝난 날부터\n5년간 보존하여야 한다.\n\n대규모유통업에서의 거래공정화에 관한 법률 (발췌·전문) ― Page 4 / 4'),
  STRUCT('regulations/02_ftc_promo_cost_guideline/sec01_scope_and_prior_agreement/guide_01_02_promo_coupon_scope', 'DOC_02_FTC_PROMO_GUIDE', 'regulations/02_ftc_promo_cost_guideline/sec01_scope_and_prior_agreement/guide_01_02_promo_coupon_scope', 'Ⅰ.1~2', '심사지침 Ⅰ.1~2 — 온라인 타겟팅·번들 할인쿠폰의 판매촉진비용 해당성', 'BASE_CRITERIA', 'ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio,ont_orders.delivered_at,ont_orders.return_requested_at', CAST(NULL AS STRING), 'gs://kmarket_okf/okf/regulations/02_ftc_promo_cost_guideline/sec01_scope_and_prior_agreement/guide_01_02_promo_coupon_scope.md', '# 심사지침 Ⅰ.1~2 — 온라인 타겟팅·번들 할인쿠폰의 판매촉진비용 해당성\n\n* **상위 문서 (`Source Document`)**: [대규모유통업 분야 판매촉진비용 부담전가 행위에 대한 위법성 심사지침 (공정위 예규 제445호)](/regulations/02_ftc_promo_cost_guideline/doc.md)[^origin_pdf]\n* **출처 페이지**: `02_FTC_대규모유통업법_판매촉진비용부담전가_심사지침_2025.pdf` — **1쪽** (`section_number: Ⅰ.1~2`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n1. 목적\n이 지침은 「대규모유통업에서의 거래공정화에 관한 법률」(이하 "법"이라 한다)\n제11조(판매촉진비용의 부담전가 금지)의 요건을 구체화하여 온라인 플랫폼 및\n대규모유통업자의 할인쿠폰 발행, 타임특가, 번들 프로모션 시 납품업자 보호와 법 집행의\n일관성을 확보함을 목적으로 한다.\n2. 판매촉진비용의 정의 및 산입 범위\n가. 판매촉진행사란 명칭이나 형식에 관계없이 상품의 소비자 구매수요를 유발하거나\n증진시키기 위하여 실시하는 모든 가격할인, 쿠폰 발급, 포인트 적립, 사은품 증정,\n무료배송 지원 행사를 포함한다.\n나. 온라인 쇼핑몰에서 고객 행동로그(장바구니 담기, 코디 상품 조회 등)를 기반으로\n자동 발행되는 타겟팅 할인쿠폰 및 번들 할인쿠폰 역시 법 제11조의 판매촉진행사에\n해당하며, 그 할인차액(쿠폰할인액)을 납품업자에게 분담시키려면 반드시 법\n제11조제1항·제2항의 사전 서면약정 요건과 제4항의 50% 분담 상한 요건을 모두\n충족하여야 한다.'),
  STRUCT('regulations/02_ftc_promo_cost_guideline/sec01_scope_and_prior_agreement/guide_03_prior_written_agreement_rule', 'DOC_02_FTC_PROMO_GUIDE', 'regulations/02_ftc_promo_cost_guideline/sec01_scope_and_prior_agreement/guide_03_prior_written_agreement_rule', 'Ⅰ.3', '심사지침 Ⅰ.3 — 사전 서면약정(`signed_promo_agreement`) 체결 시점 및 포괄약정 불인정', 'BASE_CRITERIA', 'ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio,ont_orders.delivered_at,ont_orders.return_requested_at', CAST(NULL AS STRING), 'gs://kmarket_okf/okf/regulations/02_ftc_promo_cost_guideline/sec01_scope_and_prior_agreement/guide_03_prior_written_agreement_rule.md', '# 심사지침 Ⅰ.3 — 사전 서면약정(`signed_promo_agreement`) 체결 시점 및 포괄약정 불인정\n\n* **상위 문서 (`Source Document`)**: [대규모유통업 분야 판매촉진비용 부담전가 행위에 대한 위법성 심사지침 (공정위 예규 제445호)](/regulations/02_ftc_promo_cost_guideline/doc.md)[^origin_pdf]\n* **출처 페이지**: `02_FTC_대규모유통업법_판매촉진비용부담전가_심사지침_2025.pdf` — **1쪽** (`section_number: Ⅰ.3`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n3. 사전 서면약정 체결 시점 및 방식\n가. 사전 서면약정은 해당 프로모션이나 쿠폰 발급이 개시되기 이전에 양 당사자의 서명\n또는 전자서명이 완료되어야 한다.\n나. 연간 기본계약서에 포괄적으로 \'프로모션 시 비용을 분담한다\'는 문구만 둔 경우에는\n법 제11조제2항의 사전 서면약정으로 인정하지 아니하며, 개별 행사 단위 또는 구체적인\n자동화 타겟팅 캠페인 단위로 품목·기간·예상비용·분담비율이 명시된 사전\n약정(`signed_promo_agreement = True`)이 존재하여야 한다.\n\n대규모유통업 분야 판매촉진비용 부담전가 행위에 대한 위법성 심사지침 ― Page 1 / 2'),
  STRUCT('regulations/02_ftc_promo_cost_guideline/sec02_cap_override_and_voluntary_test/guide_04_fifty_percent_cap_invalidity', 'DOC_02_FTC_PROMO_GUIDE', 'regulations/02_ftc_promo_cost_guideline/sec02_cap_override_and_voluntary_test/guide_04_fifty_percent_cap_invalidity', 'Ⅱ.4', '심사지침 Ⅱ.4 — 50% 초과 약정(`promo_cost_share_ratio > 0.50`) 당연 무효 및 유통업자 부담 원칙', 'EXCEPTION_PROVISO', 'ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio,ont_orders.delivered_at,ont_orders.return_requested_at', CAST(NULL AS STRING), 'gs://kmarket_okf/okf/regulations/02_ftc_promo_cost_guideline/sec02_cap_override_and_voluntary_test/guide_04_fifty_percent_cap_invalidity.md', '# 심사지침 Ⅱ.4 — 50% 초과 약정(`promo_cost_share_ratio > 0.50`) 당연 무효 및 유통업자 부담 원칙\n\n* **상위 문서 (`Source Document`)**: [대규모유통업 분야 판매촉진비용 부담전가 행위에 대한 위법성 심사지침 (공정위 예규 제445호)](/regulations/02_ftc_promo_cost_guideline/doc.md)[^origin_pdf]\n* **출처 페이지**: `02_FTC_대규모유통업법_판매촉진비용부담전가_심사지침_2025.pdf` — **2쪽** (`section_number: Ⅱ.4`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n4. 납품업자 분담비율 50% 상한선 준수 및 초과분 처리\n가. 법 제11조제4항에 따라 납품업자의 판매촉진비용 분담비율은 어떠한 경우에도 총\n판매촉진비용(쿠폰 할인금액 총액 등)의 100분의 50을 초과할 수 없다.\n나. 만약 대규모유통업자와 납품업자 간 계약서상\n분담비율(`promo_cost_share_ratio`)이 60% 또는 70% 등으로\n약정되어 있더라도, 법정 상한인 50%를 초과하는 약정 부분은 강행규정 위반으로 당연\n무효이다.\n다. 따라서 대규모유통업자는 실제 쿠폰할인액의 최대 50%까지만 납품업자 정산대금에서\n공제할 수 있으며, 50%를 초과하는 나머지 금액은 대규모유통업자 자신의 마케팅\n예산으로 전액 부담하여야 한다.'),
  STRUCT('regulations/02_ftc_promo_cost_guideline/sec02_cap_override_and_voluntary_test/guide_05_voluntary_differentiated_test', 'DOC_02_FTC_PROMO_GUIDE', 'regulations/02_ftc_promo_cost_guideline/sec02_cap_override_and_voluntary_test/guide_05_voluntary_differentiated_test', 'Ⅱ.5', '심사지침 Ⅱ.5 — 법 제11조제5항 단서(자발성·차별성) 인정 요건 및 상시 캠페인 배제', 'EXCEPTION_PROVISO', 'ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio,ont_orders.delivered_at,ont_orders.return_requested_at', 'campaign_exceptions.voluntary_request_doc_uri,campaign_exceptions.expected_uplift_roi_pct', 'gs://kmarket_okf/okf/regulations/02_ftc_promo_cost_guideline/sec02_cap_override_and_voluntary_test/guide_05_voluntary_differentiated_test.md', '# 심사지침 Ⅱ.5 — 법 제11조제5항 단서(자발성·차별성) 인정 요건 및 상시 캠페인 배제\n\n* **상위 문서 (`Source Document`)**: [대규모유통업 분야 판매촉진비용 부담전가 행위에 대한 위법성 심사지침 (공정위 예규 제445호)](/regulations/02_ftc_promo_cost_guideline/doc.md)[^origin_pdf]\n* **출처 페이지**: `02_FTC_대규모유통업법_판매촉진비용부담전가_심사지침_2025.pdf` — **2쪽** (`section_number: Ⅱ.5`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n5. 법 제11조제5항 단서(자발성·차별성 요건) 예외의 엄격한 심사기준\n가. 법 제11조제5항 단서에 따라 50% 분담비율 상한 규정의 적용을 배제받기\n위해서는 해당 행사가 ① 납품업자의 자발적 요청(자발성)에 의하여 기획되었고, ② 다른\n납품업자와 차별화되는 행사(차별성)라는 두 가지 요건을 모두 충족하여야 하며, 그\n입증책임은 대규모유통업자에게 있다.\n나. 자발성 판단기준: 대규모유통업자의 기획안 배포나 권유 없이 납품업자가 독자적으로\n행사 기간·할인율·품목을 기안하여 대규모유통업자에게 먼저 공문으로 신청한 객관적 이력이\n있어야 한다. 대규모유통업자가 운영하는 상시 장바구니 리마인드 쿠폰이나 등급별 VIP\n쿠폰 캠페인에 참여하는 것은 자발적 행사로 인정되지 아니한다.\n다. 차별성 판단기준: 전 입점브랜드나 카테고리 전체를 대상으로 일괄 진행되는\n시즌오프·블랙프라이데이·VIP 정기쿠폰 행사는 차별성이 부정된다. 특정 브랜드의 단독\n신상품 런칭전 등 타 브랜드와 시기·조건이 명확히 구분되는 단독 행사여야 한다.\n\n대규모유통업 분야 판매촉진비용 부담전가 행위에 대한 위법성 심사지침 ― Page 2 / 2'),
  STRUCT('regulations/03_law_ecommerce_consumer_protection/ch01_disclosure_and_supply/ecom_art_001_013_015_disclosure_supply', 'DOC_03_LAW_ECOMMERCE', 'regulations/03_law_ecommerce_consumer_protection/ch01_disclosure_and_supply/ecom_art_001_013_015_disclosure_supply', '제1조·제13조·제15조', '제1조(목적)·제13조(거래조건 표시·고지)·제15조(선지급식 3영업일 이내 공급조치)', 'BASE_CRITERIA', 'ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio,ont_orders.delivered_at,ont_orders.return_requested_at', CAST(NULL AS STRING), 'gs://kmarket_okf/okf/regulations/03_law_ecommerce_consumer_protection/ch01_disclosure_and_supply/ecom_art_001_013_015_disclosure_supply.md', '# 제1조(목적)·제13조(거래조건 표시·고지)·제15조(선지급식 3영업일 이내 공급조치)\n\n* **상위 문서 (`Source Document`)**: [전자상거래 등에서의 소비자보호에 관한 법률 (법률 제20312호, 2025. 2. 1. 시행)](/regulations/03_law_ecommerce_consumer_protection/doc.md)[^origin_pdf]\n* **출처 페이지**: `03_LAW_전자상거래법_전문_2025.pdf` — **1쪽** (`section_number: 제1조·제13조·제15조`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n제1조(목적) 이 법은 전자상거래 및 통신판매 등에 의한 재화 또는 용역의 공정한\n거래에 관한 사항을 규정함으로써 소비자의 권익을 보호하고 시장의 신뢰도를 높여\n국민경제의 건전한 발전에 이바지함을 목적으로 한다.\n제13조(신원 및 거래조건에 대한 정보의 제공) ① 통신판매업자는 소비자가 계약체결\n전에 재화등에 대한 거래조건을 정확하게 이해하고 실수나 착오 없이 거래할 수 있도록\n다음 각 호의 사항을 적절한 방법으로 표시·광고하거나 고지하여야 한다.\n1. 재화등의 공급자 및 판매자에 관한 사항\n2. 재화등의 명칭·종류·소재·치수(실측 사이즈)·색상 및 내용\n3. 재화등의 가격(할인 전 정상가, 쿠폰 적용가 및 배송비를 구분하여 표시)\n4. 재화등의 공급방법 및 공급시기(물류센터 출고 예정일 및 배송 소요기간)\n5. 청약철회등의 기한·행사방법·효과 및 반품비용 부담에 관한 사항\n제15조(재화등의 공급 등) ① 통신판매업자는 소비자가 청약을 한 날부터 7일 이내에\n재화등의 공급에 필요한 조치를 하여야 하고, 소비자가 재화등을 공급받기 전에 미리\n재화등의 대금을 전부 또는 일부 지급한 경우(선지급식 통신판매)에는 소비자가 그 대금을\n지급한 날부터 3영업일 이내에 재화등의 공급을 위하여 필요한 조치를 하여야 한다.\n② 통신판매업자는 청약을 받은 재화등을 공급하기 곤란하다는 것을 알았을 때에는 지체\n없이 그 사유를 소비자에게 알려야 하고, 선지급식 통신판매의 경우에는 소비자가 그\n대금을 지급한 날부터 3영업일 이내에 환급하거나 환급에 필요한 조치를 하여야 한다.\n\n전자상거래 등에서의 소비자보호에 관한 법률 (발췌·전문) ― Page 1 / 3'),
  STRUCT('regulations/03_law_ecommerce_consumer_protection/ch02_withdrawal_and_exceptions/ecom_art_017_p1_withdrawal_periods', 'DOC_03_LAW_ECOMMERCE', 'regulations/03_law_ecommerce_consumer_protection/ch02_withdrawal_and_exceptions/ecom_art_017_p1_withdrawal_periods', '제17조제1항', '제17조제1항(청약철회 기간 — 제1호 단순변심 7일 vs 제2호 표시·광고 상이 3개월·30일)', 'BASE_CRITERIA', 'ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio,ont_orders.delivered_at,ont_orders.return_requested_at', CAST(NULL AS STRING), 'gs://kmarket_okf/okf/regulations/03_law_ecommerce_consumer_protection/ch02_withdrawal_and_exceptions/ecom_art_017_p1_withdrawal_periods.md', '# 제17조제1항(청약철회 기간 — 제1호 단순변심 7일 vs 제2호 표시·광고 상이 3개월·30일)\n\n* **상위 문서 (`Source Document`)**: [전자상거래 등에서의 소비자보호에 관한 법률 (법률 제20312호, 2025. 2. 1. 시행)](/regulations/03_law_ecommerce_consumer_protection/doc.md)[^origin_pdf]\n* **출처 페이지**: `03_LAW_전자상거래법_전문_2025.pdf` — **2쪽** (`section_number: 제17조제1항`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n제17조(청약철회등) ① 통신판매업자와 재화등의 구매에 관한 계약을 체결한 소비자는\n다음 각 호의 기간(거래당사자가 다음 각 호의 기간보다 긴 기간으로 약정한 경우에는 그\n기간을 말한다) 이내에 당해 계약에 관한 청약철회등을 할 수 있다.\n1. 제13조제2항에 따른 계약내용에 관한 서면을 받은 날부터 7일. 단, 그 서면을\n받은 때보다 재화등의 공급이 늦게 이루어진 경우에는 재화등을 공급받거나 재화등의 공급이\n시작된 날부터 7일(단순변심에 의한 반품·청약철회)\n2. 재화등의 내용이 표시·광고의 내용과 다르거나 계약내용과 다르게 이행된 경우에는\n당해 재화등을 공급받은 날부터 3개월 이내, 그 사실을 안 날 또는 알 수 있었던\n날부터 30일 이내(표시·광고 상이 또는 오배송·불량에 의한 반품·청약철회)'),
  STRUCT('regulations/03_law_ecommerce_consumer_protection/ch02_withdrawal_and_exceptions/ecom_art_017_p2_withdrawal_restrictions', 'DOC_03_LAW_ECOMMERCE', 'regulations/03_law_ecommerce_consumer_protection/ch02_withdrawal_and_exceptions/ecom_art_017_p2_withdrawal_restrictions', '제17조제2항', '제17조제2항(청약철회 제한 사유 — 소비자 귀책 훼손·세탁/수선/착용 흔적으로 가치 현저 감소)', 'EXCEPTION_PROVISO', 'ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio,ont_orders.delivered_at,ont_orders.return_requested_at', 'campaign_exceptions.inspection_photo_gcs_uri,order_items.seal_serial_no', 'gs://kmarket_okf/okf/regulations/03_law_ecommerce_consumer_protection/ch02_withdrawal_and_exceptions/ecom_art_017_p2_withdrawal_restrictions.md', '# 제17조제2항(청약철회 제한 사유 — 소비자 귀책 훼손·세탁/수선/착용 흔적으로 가치 현저 감소)\n\n* **상위 문서 (`Source Document`)**: [전자상거래 등에서의 소비자보호에 관한 법률 (법률 제20312호, 2025. 2. 1. 시행)](/regulations/03_law_ecommerce_consumer_protection/doc.md)[^origin_pdf]\n* **출처 페이지**: `03_LAW_전자상거래법_전문_2025.pdf` — **2쪽** (`section_number: 제17조제2항`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n② 소비자는 다음 각 호의 어느 하나에 해당하는 경우에는 통신판매업자의 의사에 반하여\n제1항에 따른 청약철회등을 할 수 없다. 다만, 통신판매업자가 제6항에 따라\n청약철회등이 불가능한 재화등에 그 사실을 포장이나 상품 상세페이지에 표시하지 아니한\n경우에는 제2호부터 제5호까지의 규정에 해당하는 경우에도 청약철회등을 할 수 있다.\n1. 소비자에게 책임 있는 사유로 재화등이 멸실되거나 훼손된 경우. 다만, 재화등의\n내용을 확인하기 위하여 포장 등을 훼손한 경우는 제외한다.\n2. 소비자의 사용 또는 일부 소비로 재화등의 가치가 현저히 감소한\n경우(의류·패션잡화의 세탁, 수선, 외부 착용 흔적 또는 향수·오염 부착을 포함한다)\n3. 시간이 지나 다시 판매하기 곤란할 정도로 재화등의 가치가 현저히 감소한 경우\n4. 복제가 가능한 재화등의 포장을 훼손한 경우\n5. 소비자의 주문에 따라 개별적으로 생산되는 재화등으로서 청약철회등을 인정하면\n통신판매업자에게 회복할 수 없는 중대한 피해가 예상되는 경우로서 사전에 해당 거래에\n대하여 별도로 그 사실을 고지하고 소비자의 서면(전자문서 포함) 동의를 받은 경우\n\n전자상거래 등에서의 소비자보호에 관한 법률 (발췌·전문) ― Page 2 / 3'),
  STRUCT('regulations/03_law_ecommerce_consumer_protection/ch03_refund_sla_and_dark_patterns/ecom_art_018_refund_and_return_shipping', 'DOC_03_LAW_ECOMMERCE', 'regulations/03_law_ecommerce_consumer_protection/ch03_refund_sla_and_dark_patterns/ecom_art_018_refund_and_return_shipping', '제18조', '제18조(청약철회의 효과 — 반환 후 3영업일 이내 환급·지연배상금 연 15%·반품배송비 귀속)', 'BASE_CRITERIA', 'ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio,ont_orders.delivered_at,ont_orders.return_requested_at', CAST(NULL AS STRING), 'gs://kmarket_okf/okf/regulations/03_law_ecommerce_consumer_protection/ch03_refund_sla_and_dark_patterns/ecom_art_018_refund_and_return_shipping.md', '# 제18조(청약철회의 효과 — 반환 후 3영업일 이내 환급·지연배상금 연 15%·반품배송비 귀속)\n\n* **상위 문서 (`Source Document`)**: [전자상거래 등에서의 소비자보호에 관한 법률 (법률 제20312호, 2025. 2. 1. 시행)](/regulations/03_law_ecommerce_consumer_protection/doc.md)[^origin_pdf]\n* **출처 페이지**: `03_LAW_전자상거래법_전문_2025.pdf` — **3쪽** (`section_number: 제18조`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n제18조(청약철회등의 효과) ① 소비자는 제17조제1항 또는 제3항에 따라 청약철회등을\n한 경우에는 이미 공급받은 재화등을 반환하여야 한다.\n② 통신판매업자는 재화등을 반환받은 날부터 3영업일 이내에 이미 지급받은 재화등의\n대금을 환급하여야 한다. 이 경우 통신판매업자가 소비자에게 재화등의 대금 환급을 지연한\n때에는 그 지연기간에 대하여 연 100분의 15의 지연배상금율을 곱하여 산정한\n지연배상금(이하 "지연배상금"이라 한다)을 지급하여야 한다.\n⑨ 제17조제1항제1호(단순변심)에 따른 청약철회등의 경우 공급받은 재화등의 반환에\n필요한 비용(왕복배송비)은 소비자가 부담하며, 통신판매업자는 소비자에게 청약철회등을\n이유로 위약금이나 손해배상을 청구할 수 없다.\n⑩ 제17조제1항제2호(표시·광고 내용과 다르거나 계약내용과 다르게 이행된 경우)에\n따른 청약철회등의 경우 재화등의 반환에 필요한 비용은 통신판매업자가 전액 부담한다.'),
  STRUCT('regulations/03_law_ecommerce_consumer_protection/ch03_refund_sla_and_dark_patterns/ecom_art_021_2_dark_pattern_ban', 'DOC_03_LAW_ECOMMERCE', 'regulations/03_law_ecommerce_consumer_protection/ch03_refund_sla_and_dark_patterns/ecom_art_021_2_dark_pattern_ban', '제21조의2', '제21조의2(온라인 인터페이스 눈속임 상술·허위할인·허위품절임박 금지)', 'BASE_CRITERIA', 'ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio,ont_orders.delivered_at,ont_orders.return_requested_at', CAST(NULL AS STRING), 'gs://kmarket_okf/okf/regulations/03_law_ecommerce_consumer_protection/ch03_refund_sla_and_dark_patterns/ecom_art_021_2_dark_pattern_ban.md', '# 제21조의2(온라인 인터페이스 눈속임 상술·허위할인·허위품절임박 금지)\n\n* **상위 문서 (`Source Document`)**: [전자상거래 등에서의 소비자보호에 관한 법률 (법률 제20312호, 2025. 2. 1. 시행)](/regulations/03_law_ecommerce_consumer_protection/doc.md)[^origin_pdf]\n* **출처 페이지**: `03_LAW_전자상거래법_전문_2025.pdf` — **3쪽** (`section_number: 제21조의2`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n제21조의2(온라인 인터페이스 운영에 있어서의 눈속임 상술 금지) 전자상거래를 하는\n사업자 또는 통신판매업자는 재화등의 거래와 관련하여 소비자의 착오나 부주의를 유발하여\n비합리적인 지출이나 의사결정을 유도하는 다음 각 호의 행위(온라인 다크패턴)를 하여서는\n아니 된다.\n1. 재화등의 구매에 드는 총비용이 아니라 일부 금액만 첫 화면에 표시하고 결제\n단계에서 추가 비용을 순차적으로 공개하는 행위\n2. 종전 거래가격이나 정가를 허위로 부풀려 할인율을 과장 표시하거나, 실제 재고\n수량과 무관하게 \'품절 임박\' 문구를 허위로 노출하여 구매를 압박하는 행위\n3. 소비자가 이미 선택한 옵션이나 마케팅 수신 거절 의사를 반복적인 팝업으로\n방해하거나 변경을 유도하는 행위\n\n전자상거래 등에서의 소비자보호에 관한 법률 (발췌·전문) ― Page 3 / 3'),
  STRUCT('regulations/04_ftc_dark_pattern_and_reco_guideline/ch01_price_and_stock_truthfulness/dp_art_001_002_price_display', 'DOC_04_FTC_DARK_PATTERN', 'regulations/04_ftc_dark_pattern_and_reco_guideline/ch01_price_and_stock_truthfulness/dp_art_001_002_price_display', '제1조~제2조', '제1조(목적) 및 제2조(할인율 비교기준가격 `retail_price_krw` 및 번들 가격 구분 표시)', 'BASE_CRITERIA', 'ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio,ont_orders.delivered_at,ont_orders.return_requested_at', 'products.min_sale_price_20d_krw,products.price_reference_verified_at', 'gs://kmarket_okf/okf/regulations/04_ftc_dark_pattern_and_reco_guideline/ch01_price_and_stock_truthfulness/dp_art_001_002_price_display.md', '# 제1조(목적) 및 제2조(할인율 비교기준가격 `retail_price_krw` 및 번들 가격 구분 표시)\n\n* **상위 문서 (`Source Document`)**: [온라인 다크패턴(눈속임 상술) 자율관리 가이드라인 및 맞춤형 추천 투명성 지침](/regulations/04_ftc_dark_pattern_and_reco_guideline/doc.md)[^origin_pdf]\n* **출처 페이지**: `04_FTC_전자상거래_다크패턴_및_맞춤형광고_가이드라인_2025.pdf` — **1쪽** (`section_number: 제1조~제2조`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n제1조(목적) 이 가이드라인은 온라인 쇼핑몰 및 모바일 커머스 플랫폼이 소비자에게\n제공하는 상품 추천, 할인쿠폰, 재고 알림 인터페이스에서 소비자의 합리적 선택을\n왜곡하는 눈속임 상술(다크패턴)을 예방하고 알고리즘 추천의 투명성을 확보하기 위한\n구체적 준수사항을 정함을 목적으로 한다.\n제2조(할인율 및 비교기준가격 표시 기준) ① 사업자가 상품에 할인율이나 쿠폰 할인가를\n표시할 때에는 실제 직전 20일 이상 판매된 정상\n판매가격(`retail_price_krw`)을 기준으로 산정하여야 하며, 단기간\n인위적으로 인상한 가격을 기준으로 할인율을 산정하여서는 아니 된다.\n② 번들 상품(코디 세트 등)에 대한 패키지 할인쿠폰을 제안하는 경우, 개별 상품의\n정상 판매가격, 개별 할인액 및 최종 실결제가격(`sale_price_krw`)을\n소비자가 한눈에 비교할 수 있도록 구분하여 표시하여야 한다.'),
  STRUCT('regulations/04_ftc_dark_pattern_and_reco_guideline/ch01_price_and_stock_truthfulness/dp_art_003_stock_truthfulness', 'DOC_04_FTC_DARK_PATTERN', 'regulations/04_ftc_dark_pattern_and_reco_guideline/ch01_price_and_stock_truthfulness/dp_art_003_stock_truthfulness', '제3조', '제3조(실시간 가용재고 `available_stock` 연동 및 품절 시 대체상품 안내 원칙)', 'BASE_CRITERIA', 'ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio,ont_orders.delivered_at,ont_orders.return_requested_at', CAST(NULL AS STRING), 'gs://kmarket_okf/okf/regulations/04_ftc_dark_pattern_and_reco_guideline/ch01_price_and_stock_truthfulness/dp_art_003_stock_truthfulness.md', '# 제3조(실시간 가용재고 `available_stock` 연동 및 품절 시 대체상품 안내 원칙)\n\n* **상위 문서 (`Source Document`)**: [온라인 다크패턴(눈속임 상술) 자율관리 가이드라인 및 맞춤형 추천 투명성 지침](/regulations/04_ftc_dark_pattern_and_reco_guideline/doc.md)[^origin_pdf]\n* **출처 페이지**: `04_FTC_전자상거래_다크패턴_및_맞춤형광고_가이드라인_2025.pdf` — **1쪽** (`section_number: 제3조`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n제3조(실시간 재고 및 품절 표시의 정확성) ① 사업자가 \'품절 임박\', \'잔여 재고\nN개\' 등의 문구를 노출할 때에는 물류센터의 실시간\n가용재고(`available_stock`) 원장 데이터와 일치하여야 한다.\n② 가용재고가 0개인 품절 상품(`available_stock == 0`)을\n미끼상품으로 노출하면서 구매 단계에서만 품절 사실을 고지하는 행위는 금지되며, 품절\n시에는 즉시 \'일시품절\' 상태를 명시하고 동일 카테고리·가격대의 대체\n상품(`substitute_product_id`)을 객관적 기준에 따라 안내할 수\n있다.\n\n온라인 다크패턴(눈속임 상술) 자율관리 가이드라인 및 맞춤형 추천 투명성 지침 ― Page 1 / 2'),
  STRUCT('regulations/04_ftc_dark_pattern_and_reco_guideline/ch02_reco_transparency_and_optin/dp_art_004_005_reco_transparency_optin', 'DOC_04_FTC_DARK_PATTERN', 'regulations/04_ftc_dark_pattern_and_reco_guideline/ch02_reco_transparency_and_optin/dp_art_004_005_reco_transparency_optin', '제4조~제5조', '제4조(초개인화 추천 기준 고지) 및 제5조(장바구니 이탈 리마인드 `marketing_opt_in` 검증 의무)', 'BASE_CRITERIA', 'ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio,ont_orders.delivered_at,ont_orders.return_requested_at', CAST(NULL AS STRING), 'gs://kmarket_okf/okf/regulations/04_ftc_dark_pattern_and_reco_guideline/ch02_reco_transparency_and_optin/dp_art_004_005_reco_transparency_optin.md', '# 제4조(초개인화 추천 기준 고지) 및 제5조(장바구니 이탈 리마인드 `marketing_opt_in` 검증 의무)\n\n* **상위 문서 (`Source Document`)**: [온라인 다크패턴(눈속임 상술) 자율관리 가이드라인 및 맞춤형 추천 투명성 지침](/regulations/04_ftc_dark_pattern_and_reco_guideline/doc.md)[^origin_pdf]\n* **출처 페이지**: `04_FTC_전자상거래_다크패턴_및_맞춤형광고_가이드라인_2025.pdf` — **2쪽** (`section_number: 제4조~제5조`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n제4조(초개인화 추천 알고리즘의 기준 고지) ① 사업자가 소비자의 구매이력, 장바구니\n담기 이력(`event_type = \'cart\'`), 카테고리 선호도를 분석하여\n초개인화 상품 추천이나 맞춤형 코디\n번들(`complementary_product_id`)을 노출하는 경우, 추천 영역\n상단 또는 안내 아이콘을 통해 \'고객님의 최근 관심 상품 및 장바구니 이력을 기반으로\n추천된 상품입니다\'와 같이 주요 추천 기준을 소비자가 알기 쉽게 표시하여야 한다.\n② 입점브랜드로부터 별도의 광고비를 지급받아 상단에 노출하는 광고 상품은 개인화 추천\n상품과 명확히 구분하여 \'광고\' 표시를 부착하여야 한다.\n제5조(장바구니 이탈 리마인드 및 타겟팅 쿠폰 발송 준수사항) ① 소비자가 상품을\n장바구니에 담은 후 결제하지 않고 이탈한 경우, 사업자가 앱 푸시(App Push),\n알림톡, 문자메시지 등을 통해 리마인드 알림이나 시크릿 할인쿠폰을 발송하려면 반드시\n해당 소비자의 사전 마케팅·맞춤형 추천 수신동의(`marketing_opt_in =\nTrue`) 여부를 실시간으로 검증하여야 한다.\n② 마케팅 수신에 동의하지 아니한 소비자(`marketing_opt_in =\nFalse`)에 대하여는 장바구니 이탈 감지 쿠폰이나 개인화된 리마인드 메시지를\n발송하여서는 아니 되며, 오직 앱 내 일반 베스트셀러 영역이나 비식별 전체 공개\n배너만을 노출하여야 한다.\n\n온라인 다크패턴(눈속임 상술) 자율관리 가이드라인 및 맞춤형 추천 투명성 지침 ― Page 2 / 2'),
  STRUCT('regulations/05_pipc_behavioral_targeting_guideline/ch01_behavioral_info_definition/pipc_art_001_002_behavioral_def', 'DOC_05_PIPC_BEHAVIORAL', 'regulations/05_pipc_behavioral_targeting_guideline/ch01_behavioral_info_definition/pipc_art_001_002_behavioral_def', '제1조~제2조', '제1조(목적) 및 제2조(행태정보의 정의 및 회원 식별정보 `user_id` 결합 시 개인정보보호법 적용)', 'BASE_CRITERIA', 'ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio,ont_orders.delivered_at,ont_orders.return_requested_at', CAST(NULL AS STRING), 'gs://kmarket_okf/okf/regulations/05_pipc_behavioral_targeting_guideline/ch01_behavioral_info_definition/pipc_art_001_002_behavioral_def.md', '# 제1조(목적) 및 제2조(행태정보의 정의 및 회원 식별정보 `user_id` 결합 시 개인정보보호법 적용)\n\n* **상위 문서 (`Source Document`)**: [온라인 맞춤형 광고 개인정보보호 가이드라인 및 전자상거래 행태정보 처리 기준](/regulations/05_pipc_behavioral_targeting_guideline/doc.md)[^origin_pdf]\n* **출처 페이지**: `05_PIPC_온라인_맞춤형광고_행태정보_가이드라인_2025.pdf` — **1쪽** (`section_number: 제1조~제2조`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n제1조(목적) 이 가이드라인은 전자상거래 사업자가 이용자의 웹사이트 및 모바일 앱\n방문이력, 상품 조회, 장바구니 담기, 구매이력 등 온라인상의\n행태정보(Behavioral Information)를 수집·분석하여 초개인화 상품 추천\n및 타겟팅 마케팅에 활용할 때 준수하여야 할 개인정보 보호 원칙을 제시함을 목적으로\n한다.\n제2조(행태정보의 정의 및 구분) ① "행태정보"란 웹사이트 방문 이력, 앱 사용\n이력, 구매 및 검색 이력 등 이용자의 관심, 흥미, 기호 및 성향 등을 파악하고\n분석할 수 있는 온라인상의 이용자 활동정보를 말한다.\n② 전자상거래 플랫폼이 행태정보를 특정 회원의 식별정보(`user_id`, 이름,\n휴대전화번호, 이메일 등)와 결합하여 처리하는 경우, 해당 정보는 「개인정보 보호법」상\n개인정보에 해당하므로 개인정보 처리 동의 및 마케팅 활용 동의 규정을 엄격히 준수하여야\n한다.\n\n온라인 맞춤형 광고 개인정보보호 가이드라인 및 전자상거래 행태정보 처리 기준 ― Page 1 / 2'),
  STRUCT('regulations/05_pipc_behavioral_targeting_guideline/ch02_optin_and_night_push_ban/pipc_art_003_optin_requirement', 'DOC_05_PIPC_BEHAVIORAL', 'regulations/05_pipc_behavioral_targeting_guideline/ch02_optin_and_night_push_ban/pipc_art_003_optin_requirement', '제3조', '제3조(식별 결합 행태정보 기반 타겟팅 마케팅 `marketing_opt_in = True` 필수 및 미동의자 차단)', 'BASE_CRITERIA', 'ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio,ont_orders.delivered_at,ont_orders.return_requested_at', CAST(NULL AS STRING), 'gs://kmarket_okf/okf/regulations/05_pipc_behavioral_targeting_guideline/ch02_optin_and_night_push_ban/pipc_art_003_optin_requirement.md', '# 제3조(식별 결합 행태정보 기반 타겟팅 마케팅 `marketing_opt_in = True` 필수 및 미동의자 차단)\n\n* **상위 문서 (`Source Document`)**: [온라인 맞춤형 광고 개인정보보호 가이드라인 및 전자상거래 행태정보 처리 기준](/regulations/05_pipc_behavioral_targeting_guideline/doc.md)[^origin_pdf]\n* **출처 페이지**: `05_PIPC_온라인_맞춤형광고_행태정보_가이드라인_2025.pdf` — **2쪽** (`section_number: 제3조`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n제3조(식별 결합 행태정보 기반 타겟팅 마케팅의 동의 요건) ① 전자상거래 사업자가\n특정 회원(`user_id`)의 실시간 이벤트 로그(`events` 테이블의\n`view`, `cart`, `purchase` 등)를 회원 원장(`users`)과\n결합하여 개인별 맞춤형 할인쿠폰을 발급하거나 타겟팅 메시지를 전송하려는 경우, 사전에\n정보주체로부터 \'개인정보의 마케팅 및 맞춤형 추천 활용\n동의\'(`marketing_opt_in = True`)를 명시적으로 받아야 한다.\n② 정보주체가 마케팅 및 맞춤형 추천 활용에 동의하지 아니한\n경우(`marketing_opt_in = False`), 사업자는 해당 회원의 장바구니\n이탈 로그나 조회 로그를 회원 식별자(`user_id`)와 결합하여 타겟팅 쿠폰을\n발급하거나 개인화 추천을 실행할 수 없다. 다만, 개인을 식별할 수 없도록 통계 처리된\n연령대별·카테고리별 일반 인기상품 정보는 노출할 수 있다.'),
  STRUCT('regulations/05_pipc_behavioral_targeting_guideline/ch02_optin_and_night_push_ban/pipc_art_004_005_retention_and_night_ban', 'DOC_05_PIPC_BEHAVIORAL', 'regulations/05_pipc_behavioral_targeting_guideline/ch02_optin_and_night_push_ban/pipc_art_004_005_retention_and_night_ban', '제4조~제5조', '제4조(행태정보 90일 보유기간·동의철회권) 및 제5조(야간 21시~08시 광고성 정보 전송 제한)', 'BASE_CRITERIA', 'ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio,ont_orders.delivered_at,ont_orders.return_requested_at', 'users.night_push_opt_in_yn,events.push_scheduled_at', 'gs://kmarket_okf/okf/regulations/05_pipc_behavioral_targeting_guideline/ch02_optin_and_night_push_ban/pipc_art_004_005_retention_and_night_ban.md', '# 제4조(행태정보 90일 보유기간·동의철회권) 및 제5조(야간 21시~08시 광고성 정보 전송 제한)\n\n* **상위 문서 (`Source Document`)**: [온라인 맞춤형 광고 개인정보보호 가이드라인 및 전자상거래 행태정보 처리 기준](/regulations/05_pipc_behavioral_targeting_guideline/doc.md)[^origin_pdf]\n* **출처 페이지**: `05_PIPC_온라인_맞춤형광고_행태정보_가이드라인_2025.pdf` — **2쪽** (`section_number: 제4조~제5조`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n제4조(행태정보 보유기간 및 통제권 보장) ① 맞춤형 추천 및 타겟팅 광고 목적으로\n수집된 상세 이벤트 로그는 수집일로부터 최대 90일 이내에 파기하거나 비식별 통계로\n전환하는 것을 원칙으로 한다.\n② 회원이 마이페이지 등에서 언제든지 마케팅 활용\n동의(`marketing_opt_in`)를 철회할 수 있는 인터페이스를 제공하여야\n하며, 동의 철회 즉시 실시간 추천 파이프라인에서 해당 회원의 개인화 타겟팅을\n중단하여야 한다.\n제5조(야간 시간대 영리목적 광고성 정보 전송 제한) 「정보통신망 이용촉진 및 정보보호\n등에 관한 법률」 제50조제3항에 따라 전자상거래 사업자가 오후 9시(21:00)부터\n그 다음 날 오전 8시(08:00)까지의 야간 시간대에 전자우편, 문자메시지, 모바일\n앱 푸시 등을 이용하여 영리목적의 광고성 정보(장바구니 리마인드 쿠폰 알림 포함)를\n전송하려는 경우에는 일반 마케팅 동의 외에 별도의 야간 광고성 정보 수신동의를 받아야\n한다. 별도 야간 동의가 없는 회원에 대한 리마인드 쿠폰 발송은 오전 8시 이후 주간\n시간대에만 실행하여야 한다.\n\n온라인 맞춤형 광고 개인정보보호 가이드라인 및 전자상거래 행태정보 처리 기준 ― Page 2 / 2'),
  STRUCT('distractors/06_distractor_customs_overseas_direct/ch01_overseas_customs_scope/dist_customs_art_001_002_scope', 'DOC_06_DISTRACTOR_CUSTOMS', 'distractors/06_distractor_customs_overseas_direct/ch01_overseas_customs_scope/dist_customs_art_001_002_scope', '제1조~제2조', '[타 업권 대조군] 관세청 고시 제1조·제2조 — 해외직구 특송물품 목록통관(미화 150달러) 및 국내 물류센터 제외', 'DISTRACTOR_RULE', 'ont_orders.order_id,ont_inventory_items.distribution_center', CAST(NULL AS STRING), 'gs://kmarket_okf/okf/distractors/06_distractor_customs_overseas_direct/ch01_overseas_customs_scope/dist_customs_art_001_002_scope.md', '# [타 업권 대조군] 관세청 고시 제1조·제2조 — 해외직구 특송물품 목록통관(미화 150달러) 및 국내 물류센터 제외\n\n* **상위 문서 (`Source Document`)**: [[Distractor] 목록통관 및 특송물품 수입통관 사무처리에 관한 고시 (관세청 고시 제2025-12호)](/distractors/06_distractor_customs_overseas_direct/doc.md)[^origin_pdf]\n* **출처 페이지**: `06_DISTRACTOR_관세청_해외직구_목록통관_및_특송물품_고시_2025.pdf` — **1쪽** (`section_number: 제1조~제2조`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n제1조(목적 및 적용범위) ① 이 고시는 「관세법」 제254조의2에 따라 외국\n전자상거래 쇼핑몰 또는 해외 물류센터로부터 국제특송화물로 반입되는 해외직구 물품의\n목록통관 및 수입신고 절차를 규정함을 목적으로 한다.\n② 이 고시는 해외 판매자로부터 국제특송업체(항공·해운 특송)를 통하여 국내\n보세구역으로 반입되는 해외직구 및 해외 구매대행 물품에 한하여 적용하며, 국내 소재\n물류센터(김포·용인·양산 등 국내 풀필먼트 센터)에서 출고되는 국내\n직매입·특약매입·위탁배송 상품 거래에는 적용하지 아니한다.\n제2조(목록통관 면세 한도 및 개인통관고유부호) ① 국내 거주자가 자가사용 목적으로\n반입하는 물품으로서 물품가격이 미화 150달러(미국발 특송물품은 미화 200달러)\n이하인 경우 목록통관으로 관세 및 부가가치세를 면제한다.\n② 목록통관을 신청하려는 특송업체는 수하인의 개인통관고유부호(P로 시작하는 13자리\n번호)를 세관장에게 제출하여야 한다.\n\n목록통관 및 특송물품 수입통관 사무처리에 관한 고시 ― Page 1 / 2'),
  STRUCT('distractors/06_distractor_customs_overseas_direct/ch01_overseas_customs_scope/dist_customs_art_003_return_fee', 'DOC_06_DISTRACTOR_CUSTOMS', 'distractors/06_distractor_customs_overseas_direct/ch01_overseas_customs_scope/dist_customs_art_003_return_fee', '제3조', '[타 업권 대조군] 관세청 고시 제3조 — 해외직구 14일 반송기한 및 국제반송수수료 35,000원 (국내 통신판매 혼동 금지)', 'DISTRACTOR_RULE', 'ont_orders.order_id,ont_inventory_items.distribution_center', CAST(NULL AS STRING), 'gs://kmarket_okf/okf/distractors/06_distractor_customs_overseas_direct/ch01_overseas_customs_scope/dist_customs_art_003_return_fee.md', '# [타 업권 대조군] 관세청 고시 제3조 — 해외직구 14일 반송기한 및 국제반송수수료 35,000원 (국내 통신판매 혼동 금지)\n\n* **상위 문서 (`Source Document`)**: [[Distractor] 목록통관 및 특송물품 수입통관 사무처리에 관한 고시 (관세청 고시 제2025-12호)](/distractors/06_distractor_customs_overseas_direct/doc.md)[^origin_pdf]\n* **출처 페이지**: `06_DISTRACTOR_관세청_해외직구_목록통관_및_특송물품_고시_2025.pdf` — **2쪽** (`section_number: 제3조`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n제3조(해외직구 물품의 반송기한 및 반송수수료 특례) ① 해외직구 특송물품에 대하여\n수하인이 반입 후 14일 이내에 국제반송을 요청하는 경우 국제항공 반송운임(건당 최소\n35,000원) 및 보세창고 보관료를 수하인이 부담한다.\n② 본 조의 14일 반송기한 및 건당 35,000원 국제반송수수료 규정은 해외 특송화물\n통관절차에 관한 특칙으로서, 국내 전자상거래 통신판매업자(K마켙 등 국내 플랫폼)가\n국내 물류센터에서 출고한 상품의 청약철회·반품(전자상거래법 제17조·제18조 적용\n대상)에 혼동하여 적용하여서는 아니 된다.\n\n목록통관 및 특송물품 수입통관 사무처리에 관한 고시 ― Page 2 / 2'),
  STRUCT('internal_policies/07_kmarket_crm_hyper_personalization/ch01_cart_abandon_and_optin_gate/crm_art_001_002_cart_abandon_optin', 'DOC_07_KMARKET_CRM_POLICY', 'internal_policies/07_kmarket_crm_hyper_personalization/ch01_cart_abandon_and_optin_gate/crm_art_001_002_cart_abandon_optin', '제1조~제2조', '내규 제1조·제2조 — 장바구니 이탈(`event_type = \'cart\'`) 탐지 및 `users.marketing_opt_in = True` 필수 검증', 'INTERNAL_RULE', 'users.marketing_opt_in,products.cost_krw,ont_inventory_items.available_stock,ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio', CAST(NULL AS STRING), 'gs://kmarket_okf/okf/internal_policies/07_kmarket_crm_hyper_personalization/ch01_cart_abandon_and_optin_gate/crm_art_001_002_cart_abandon_optin.md', '# 내규 제1조·제2조 — 장바구니 이탈(`event_type = \'cart\'`) 탐지 및 `users.marketing_opt_in = True` 필수 검증\n\n* **상위 문서 (`Source Document`)**: [K마켙 초개인화 추천 알고리즘 및 CRM 타겟팅 쿠폰 운영내규 (제CRM-2025-01호)](/internal_policies/07_kmarket_crm_hyper_personalization/doc.md)[^origin_pdf]\n* **출처 페이지**: `07_INTERNAL_K마켙_초개인화추천_및_CRM타겟팅_운영내규_2025.pdf` — **1쪽** (`section_number: 제1조~제2조`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n제1조(목적) 이 내규는 주식회사 K마켙(이하 "당사"라 한다)이 운영하는 온라인\n패션·라이프스타일 플랫폼에서 고객 행동로그와 상품·재고 원장을 결합하여 초개인화 상품\n추천 및 타겟팅 할인쿠폰을 발급할 때 준수하여야 할 비즈니스 의사결정 기준과\n개인정보·공정거래 가드레일을 정함을 목적으로 한다.\n제2조(장바구니 미결제 이탈 고객 실시간 탐지 및 동의 검증 의무) ① AI추천랩 및\nCRM 시스템은 실시간 행동로그 원장(`events`)에서 이벤트 유형이 장바구니\n담기(`event_type = \'cart\'`)로 기록된 후 동일\n세션(`session_id`) 내에 결제완료(`purchase`) 이벤트가 발생하지\n아니한 미결제 이탈 고객을 실시간 탐지한다.\n② 제1항에 따라 탐지된 고객에게 장바구니 리마인드 알림이나 개인화 타겟팅 쿠폰을\n발급하기 전에, 반드시 회원 원장(`users`)의 마케팅 및 맞춤형 추천 동의\n여부(`marketing_opt_in`)를 조회하여야 한다.\n③ `users.marketing_opt_in = True`인 회원에 한하여 개인화\n추천 및 타겟팅 쿠폰을 발급할 수 있으며, `users.marketing_opt_in\n= False`인 회원에 대하여는 어떠한 경우에도 개인 식별 기반 리마인드 푸시나\n타겟팅 쿠폰을 발급하여서는 아니 된다(개인정보보호위원회 행태정보 가이드라인 제3조\n준수).\n\nK마켙 초개인화 추천 알고리즘 및 CRM 타겟팅 쿠폰 운영내규 ― Page 1 / 2'),
  STRUCT('internal_policies/07_kmarket_crm_hyper_personalization/ch02_bundle_substitute_and_tier_coupon/crm_art_003_stock_substitute_bundle', 'DOC_07_KMARKET_CRM_POLICY', 'internal_policies/07_kmarket_crm_hyper_personalization/ch02_bundle_substitute_and_tier_coupon/crm_art_003_stock_substitute_bundle', '제3조', '내규 제3조 — 품절(`available_stock == 0`) 시 대체상품(`substitute_product_id`) 전환 및 정상재고 시 코디 번들(`complementary_product_id`) 추천', 'EXCEPTION_PROVISO', 'users.marketing_opt_in,products.cost_krw,ont_inventory_items.available_stock,ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio', CAST(NULL AS STRING), 'gs://kmarket_okf/okf/internal_policies/07_kmarket_crm_hyper_personalization/ch02_bundle_substitute_and_tier_coupon/crm_art_003_stock_substitute_bundle.md', '# 내규 제3조 — 품절(`available_stock == 0`) 시 대체상품(`substitute_product_id`) 전환 및 정상재고 시 코디 번들(`complementary_product_id`) 추천\n\n* **상위 문서 (`Source Document`)**: [K마켙 초개인화 추천 알고리즘 및 CRM 타겟팅 쿠폰 운영내규 (제CRM-2025-01호)](/internal_policies/07_kmarket_crm_hyper_personalization/doc.md)[^origin_pdf]\n* **출처 페이지**: `07_INTERNAL_K마켙_초개인화추천_및_CRM타겟팅_운영내규_2025.pdf` — **2쪽** (`section_number: 제3조`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n제3조(가용재고 연동 대체상품 및 크로스셀 코디 번들 추천 규칙) ① 장바구니 이탈\n고객 또는 상품 상세 조회 고객에게 상품을 추천할 때에는 먼저 물류\n원장(`inventory_items`)의 실시간\n가용재고(`available_stock`)를 확인하여야 한다.\n② 고객이 관심을 보인 주상품의 가용재고가 0개인 품절\n상태(`available_stock == 0`)인 경우에는 해당 상품에 대한 쿠폰\n발급을 즉시 중단하고, 상품 마스터(`products`)에 지정된 동일 카테고리·유사\n가격대의 대체 추천 상품(`substitute_product_id`)을 우선 추천하여야\n한다.\n③ 주상품의 가용재고가 1개 이상 정상 확보(`available_stock >=\n1`)되어 있는 경우에는 객단가(AOV) 증대를 위하여 상품\n마스터(`products`)에 연결된 연관 코디·보완\n상품(`complementary_product_id`)을 함께 묶은 \'코디 세트\n번들(Cross-sell Bundle)\'로 추천할 수 있다.'),
  STRUCT('internal_policies/07_kmarket_crm_hyper_personalization/ch02_bundle_substitute_and_tier_coupon/crm_art_004_005_tier_coupon_and_night_rule', 'DOC_07_KMARKET_CRM_POLICY', 'internal_policies/07_kmarket_crm_hyper_personalization/ch02_bundle_substitute_and_tier_coupon/crm_art_004_005_tier_coupon_and_night_rule', '제4조~제5조', '내규 제4조(VIP·VVIP 최대 15% 할인쿠폰 및 25% 마진 가드레일 연동)·제5조(야간 푸시 차단)', 'EXCEPTION_PROVISO', 'users.marketing_opt_in,products.cost_krw,ont_inventory_items.available_stock,ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio', 'users.night_push_opt_in_yn,events.push_scheduled_at', 'gs://kmarket_okf/okf/internal_policies/07_kmarket_crm_hyper_personalization/ch02_bundle_substitute_and_tier_coupon/crm_art_004_005_tier_coupon_and_night_rule.md', '# 내규 제4조(VIP·VVIP 최대 15% 할인쿠폰 및 25% 마진 가드레일 연동)·제5조(야간 푸시 차단)\n\n* **상위 문서 (`Source Document`)**: [K마켙 초개인화 추천 알고리즘 및 CRM 타겟팅 쿠폰 운영내규 (제CRM-2025-01호)](/internal_policies/07_kmarket_crm_hyper_personalization/doc.md)[^origin_pdf]\n* **출처 페이지**: `07_INTERNAL_K마켙_초개인화추천_및_CRM타겟팅_운영내규_2025.pdf` — **2쪽** (`section_number: 제4조~제5조`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n제4조(회원 등급별 타겟팅 쿠폰 할인율 상한 및 마진 가드레일 연동) ① 마케팅\n수신동의(`marketing_opt_in = True`)가 확인된 회원에 대하여 부여할\n수 있는 CRM 타겟팅 쿠폰의 최대 할인율은 회원\n등급(`membership_tier`)별로 다음과 같이 운영한다.\n1. VVIP 및 VIP 등급 회원: 정상 판매가(`retail_price_krw`)\n대비 최대 15% 할인쿠폰(단품 또는 코디 번들 전체 적용 가능)\n2. GOLD 등급 회원: 정상 판매가 대비 최대 10% 할인쿠폰\n3. SILVER 등급 회원: 정상 판매가 대비 최대 5% 할인쿠폰\n② 제1항에 따른 쿠폰을 발급할 때에는 개별 상품별로 쿠폰 적용 후\n실결제가격(`sale_price_krw`) 기준 매출총이익률이 「K마켙 MD 상품마진\n가드레일 및 체화재고 가격결정 내규」 제2조의 상시 최저마진율(25%) 이상인지 반드시\n사전 검증하여야 한다. 만약 번들 내 특정 상품의 쿠폰 적용 후 마진율이 25%\n미만으로 하락하는 경우에는 해당 상품에 대한 체화재고 완화 특례(내규 제3조) 또는\nMD본부 사전 예외승인(`campaign_exceptions`)이 존재하는 때에만 쿠폰\n적용을 허용한다.\n제5조(야간 발송 차단 및 추천 투명성 문구 표기) ① 모든 CRM 리마인드 푸시 및\n알림톡은 오전 08:00부터 오후 21:00 사이에만 발송하며, 21:00 이후 발생한\n장바구니 이탈 건은 익일 오전 08:30에 예약 발송한다.\n② 코디 번들 및 대체상품 추천 카드 하단에는 \'고객님의 최근 장바구니 및 관심 상품을\n기반으로 추천되었습니다\'라는 투명성 안내 문구를 필수 표기한다.\n\nK마켙 초개인화 추천 알고리즘 및 CRM 타겟팅 쿠폰 운영내규 ― Page 2 / 2'),
  STRUCT('internal_policies/08_kmarket_md_margin_and_clearance/ch01_margin_formula_and_25pct_guardrail/md_art_001_002_margin_25pct_guardrail', 'DOC_08_KMARKET_MD_POLICY', 'internal_policies/08_kmarket_md_margin_and_clearance/ch01_margin_formula_and_25pct_guardrail/md_art_001_002_margin_25pct_guardrail', '제1조~제2조', '내규 제1조·제2조 — 실현마진율 산식(`(sale_price_krw - cost_krw) / sale_price_krw`) 및 상시 25.0% 하한 가드레일', 'INTERNAL_RULE', 'users.marketing_opt_in,products.cost_krw,ont_inventory_items.available_stock,ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio', CAST(NULL AS STRING), 'gs://kmarket_okf/okf/internal_policies/08_kmarket_md_margin_and_clearance/ch01_margin_formula_and_25pct_guardrail/md_art_001_002_margin_25pct_guardrail.md', '# 내규 제1조·제2조 — 실현마진율 산식(`(sale_price_krw - cost_krw) / sale_price_krw`) 및 상시 25.0% 하한 가드레일\n\n* **상위 문서 (`Source Document`)**: [K마켙 MD 상품마진 가드레일 및 체화재고 클리어런스 가격결정 내규 (제MD-2025-02호)](/internal_policies/08_kmarket_md_margin_and_clearance/doc.md)[^origin_pdf]\n* **출처 페이지**: `08_INTERNAL_K마켙_MD상품마진_및_체화재고_가격결정_내규_2025.pdf` — **1쪽** (`section_number: 제1조~제2조`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n제1조(목적) 이 내규는 K마켙에서 판매되는 직매입·특약매입·위수탁 상품의 수익성을\n방어하고 무분별한 할인쿠폰 남발로 인한 역마진을 방지하기 위하여, 상품 마진율 산정\n산식과 상시 최저마진 가드레일 및 체화재고(악성재고) 클리어런스 특례 기준을 정함을\n목적으로 한다.\n제2조(매출총이익률 산식 및 상시 프로모션 최저마진 25% 가드레일) ① 개별 상품의\n프로모션 적용 후 매출총이익률(Gross Margin Ratio, 이하\n"실현마진율"이라 한다)은 다음 산식에 의하여 계산한다.\n* 실현마진율 = (`sale_price_krw` - `cost_krw`) /\n`sale_price_krw`\n(여기서 `sale_price_krw`는 정상 판매가\n`retail_price_krw`에서 쿠폰할인액\n`coupon_discount_krw`를 차감한 고객 실결제가격이며,\n`cost_krw`는 상품 매입원가이다.)\n② 모든 상시 프로모션, CRM 타겟팅 쿠폰 및 코디 번들 할인 적용 시 개별 상품의\n실현마진율은 100분의 25(25.0%) 이상을 유지하여야 한다(상시 최저마진\n가드레일).\n③ 기본 마진율(`(retail_price_krw - cost_krw) /\nretail_price_krw`)이 낮아 할인쿠폰 적용 시 실현마진율이 25.0%\n미만으로 하락하는 저마진 상품은 원칙적으로 자동 할인쿠폰 적용 대상에서\n제외(Block)하여야 한다.\n\nK마켙 MD 상품마진 가드레일 및 체화재고 클리어런스 가격결정 내규 ― Page 1 / 2'),
  STRUCT('internal_policies/08_kmarket_md_margin_and_clearance/ch02_aged_inventory_clearance_and_exceptions/md_art_003_aged_inventory_10pct_floor', 'DOC_08_KMARKET_MD_POLICY', 'internal_policies/08_kmarket_md_margin_and_clearance/ch02_aged_inventory_clearance_and_exceptions/md_art_003_aged_inventory_10pct_floor', '제3조', '내규 제3조 — 체화재고(`stock_age_days >= 90` & `available_stock >= 30`) 최저마진 10.0% 완화 및 최대 30% 클리어런스 할인 특례', 'EXCEPTION_PROVISO', 'users.marketing_opt_in,products.cost_krw,ont_inventory_items.available_stock,ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio', CAST(NULL AS STRING), 'gs://kmarket_okf/okf/internal_policies/08_kmarket_md_margin_and_clearance/ch02_aged_inventory_clearance_and_exceptions/md_art_003_aged_inventory_10pct_floor.md', '# 내규 제3조 — 체화재고(`stock_age_days >= 90` & `available_stock >= 30`) 최저마진 10.0% 완화 및 최대 30% 클리어런스 할인 특례\n\n* **상위 문서 (`Source Document`)**: [K마켙 MD 상품마진 가드레일 및 체화재고 클리어런스 가격결정 내규 (제MD-2025-02호)](/internal_policies/08_kmarket_md_margin_and_clearance/doc.md)[^origin_pdf]\n* **출처 페이지**: `08_INTERNAL_K마켙_MD상품마진_및_체화재고_가격결정_내규_2025.pdf` — **2쪽** (`section_number: 제3조`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n제3조(체화재고의 정의 및 클리어런스 마진 하한 완화 특례) ① 물류\n원장(`inventory_items`)상 입고 후\n경과일수(`stock_age_days`)가 90일 이상이고\n가용재고(`available_stock`)가 30개 이상 누적된 상품은\n\'체화재고(Slow-moving / Aged Inventory)\'로 분류한다.\n② 제2조제2항에도 불구하고, 제1항의 체화재고(`stock_age_days >=\n90`)에 해당하는 상품에 대하여는 창고 보관료 절감 및 현금흐름 회수를 위하여\n최저마진 가드레일 하한선을 100분의 25(25.0%)에서 100분의\n10(10.0%)으로 완화하며, 정상 판매가 대비 최대 30%까지 클리어런스 할인쿠폰\n또는 번들 할인을 적용할 수 있다.'),
  STRUCT('internal_policies/08_kmarket_md_margin_and_clearance/ch02_aged_inventory_clearance_and_exceptions/md_art_004_campaign_exception_override', 'DOC_08_KMARKET_MD_POLICY', 'internal_policies/08_kmarket_md_margin_and_clearance/ch02_aged_inventory_clearance_and_exceptions/md_art_004_campaign_exception_override', '제4조', '내규 제4조 — 캠페인 예외승인 원장(`campaign_exceptions`) `APPROVED` 검증 및 기각/만료 건 사용 금지', 'EXCEPTION_PROVISO', 'users.marketing_opt_in,products.cost_krw,ont_inventory_items.available_stock,ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio', CAST(NULL AS STRING), 'gs://kmarket_okf/okf/internal_policies/08_kmarket_md_margin_and_clearance/ch02_aged_inventory_clearance_and_exceptions/md_art_004_campaign_exception_override.md', '# 내규 제4조 — 캠페인 예외승인 원장(`campaign_exceptions`) `APPROVED` 검증 및 기각/만료 건 사용 금지\n\n* **상위 문서 (`Source Document`)**: [K마켙 MD 상품마진 가드레일 및 체화재고 클리어런스 가격결정 내규 (제MD-2025-02호)](/internal_policies/08_kmarket_md_margin_and_clearance/doc.md)[^origin_pdf]\n* **출처 페이지**: `08_INTERNAL_K마켙_MD상품마진_및_체화재고_가격결정_내규_2025.pdf` — **2쪽** (`section_number: 제4조`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n제4조(캠페인 예외승인 원장 검증 및 우회 기준) ① 체화재고 완화 요건이나 상시\n마진율 25% 기준에 대한 예외를 적용하여 CRM 번들 쿠폰이나 클리어런스 특가를\n실행하려는 경우, 실시간 캠페인 예외승인\n원장(`campaign_exceptions`)에 승인 상태(`status =\n\'APPROVED\'`)로 등록된 유효한 예외승인 코드(`exception_id`)가\n존재하는지 확인하여야 한다.\n② 적격 예외승인 유형(`exception_type`)은 다음 각 호와 같다.\n1. `CLEARANCE_OVERRIDE`: 체화재고(`stock_age_days >=\n90`) 또는 시즌오프 재고 소진을 위하여 MD본부장이 최저마진 하한을 승인된\n하한율(`approved_margin_floor`, 최소 10% 이상)까지 완화 승인한\n건\n2. `VIP_RETENTION`: VVIP·VIP 핵심 고객의 이탈 방지를 위하여\n그로스마케팅본부장 및 MD본부장이 합의하여 코디 번들 구성 상품의 마진 하한을\n한시적으로 완화 승인한 건\n③ 승인 상태가 기각(`REJECTED`)이거나 만료(`EXPIRED`)된 예외승인\n건은 가격결정 및 쿠폰 발급의 근거로 사용할 수 없다.\n\nK마켙 MD 상품마진 가드레일 및 체화재고 클리어런스 가격결정 내규 ― Page 2 / 2'),
  STRUCT('internal_policies/09_kmarket_vendor_promo_settlement/ch01_prior_agreement_verification/partner_art_001_002_prior_agreement', 'DOC_09_KMARKET_PARTNER_POLICY', 'internal_policies/09_kmarket_vendor_promo_settlement/ch01_prior_agreement_verification/partner_art_001_002_prior_agreement', '제1조~제2조', '내규 제1조·제2조 — 사전 서면약정(`signed_promo_agreement`) 검증 의무 및 미체결 시 K마켙 100% 부담', 'INTERNAL_RULE', 'users.marketing_opt_in,products.cost_krw,ont_inventory_items.available_stock,ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio', CAST(NULL AS STRING), 'gs://kmarket_okf/okf/internal_policies/09_kmarket_vendor_promo_settlement/ch01_prior_agreement_verification/partner_art_001_002_prior_agreement.md', '# 내규 제1조·제2조 — 사전 서면약정(`signed_promo_agreement`) 검증 의무 및 미체결 시 K마켙 100% 부담\n\n* **상위 문서 (`Source Document`)**: [K마켙 입점브랜드 공동프로모션 및 쿠폰분담금 정산내규 (제PARTNER-2025-03호)](/internal_policies/09_kmarket_vendor_promo_settlement/doc.md)[^origin_pdf]\n* **출처 페이지**: `09_INTERNAL_K마켙_입점브랜드_공동프로모션_정산내규_2025.pdf` — **1쪽** (`section_number: 제1조~제2조`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n제1조(목적) 이 내규는 K마켙과 입점브랜드(납품업자) 간에 실시하는 공동 프로모션,\nCRM 타겟팅 쿠폰 및 코디 번들 할인행사에 소요되는 판매촉진비용(쿠폰할인액)을\n정산함에 있어 「대규모유통업에서의 거래공정화에 관한 법률」 제11조 및 공정거래위원회\n심사지침을 철저히 준수하기 위한 내부 통제 및 정산 산식을 규정함을 목적으로 한다.\n제2조(사전 서면약정 유무 검증 의무) ① 정산시스템 및 에이전트는\n주문상품(`order_items`)에 적용된\n쿠폰할인액(`coupon_discount_krw`) 중 일부를\n입점브랜드(`brand_vendor_contracts`)에 분담시키기 전에, 반드시\n해당 브랜드 계약 원장의 사전 판촉약정 체결\n여부(`signed_promo_agreement`)를 확인하여야 한다.\n② 만약 `signed_promo_agreement = False`인 브랜드의 상품에\n쿠폰이 적용된 경우, 입점브랜드 분담금은 0원으로 처리하고 쿠폰할인액의 100%를\nK마켙 마케팅 예산에서 부담하여야 한다.\n\nK마켙 입점브랜드 공동프로모션 및 쿠폰분담금 정산내규 ― Page 1 / 2'),
  STRUCT('internal_policies/09_kmarket_vendor_promo_settlement/ch02_fifty_percent_cap_settlement_formula/partner_art_003_cap_settlement_formula', 'DOC_09_KMARKET_PARTNER_POLICY', 'internal_policies/09_kmarket_vendor_promo_settlement/ch02_fifty_percent_cap_settlement_formula/partner_art_003_cap_settlement_formula', '제3조', '내규 제3조 — 납품업자 분담비율 50% 법정 상한 캡(`MIN(promo_cost_share_ratio, 0.50)`) 적용 및 초과분 K마켙 흡수 산식', 'EXCEPTION_PROVISO', 'users.marketing_opt_in,products.cost_krw,ont_inventory_items.available_stock,ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio', CAST(NULL AS STRING), 'gs://kmarket_okf/okf/internal_policies/09_kmarket_vendor_promo_settlement/ch02_fifty_percent_cap_settlement_formula/partner_art_003_cap_settlement_formula.md', '# 내규 제3조 — 납품업자 분담비율 50% 법정 상한 캡(`MIN(promo_cost_share_ratio, 0.50)`) 적용 및 초과분 K마켙 흡수 산식\n\n* **상위 문서 (`Source Document`)**: [K마켙 입점브랜드 공동프로모션 및 쿠폰분담금 정산내규 (제PARTNER-2025-03호)](/internal_policies/09_kmarket_vendor_promo_settlement/doc.md)[^origin_pdf]\n* **출처 페이지**: `09_INTERNAL_K마켙_입점브랜드_공동프로모션_정산내규_2025.pdf` — **2쪽** (`section_number: 제3조`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n제3조(납품업자 쿠폰 분담비율 50% 법정 상한 적용 및 초과분 K마켙 흡수 원칙) ①\n사전 서면약정(`signed_promo_agreement = True`)이 체결된\n입점브랜드라 하더라도, 대규모유통업법 제11조제4항에 따라 입점브랜드가 실제로 부담하는\n판매촉진비용 분담비율은 총 쿠폰할인액(`coupon_discount_krw`)의\n100분의 50(50.0%)을 초과할 수 없다.\n② 입점브랜드 계약 원장(`brand_vendor_contracts`)에 기재된 약정\n판촉비 분담률(`promo_cost_share_ratio`)이 0.50(50%)을\n초과하는 경우(예: `promo_cost_share_ratio = 0.60` 즉 60%\n약정), 정산 시에는 법정 상한인 0.50(50%)으로 자동 캡(Cap)을 씌워\n산정하며, 약정 분담률과 법정 상한(50%)의 차액에 해당하는 초과분은 전액 K마켙이\n흡수하여 부담한다.\n③ 구체적인 주문건별·브랜드별 쿠폰 분담금 정산 산식은 다음과 같다.\n1. 약정 기준 브랜드 분담액(캡 적용 전) =\n`coupon_discount_krw` × `promo_cost_share_ratio`\n2. 법정 유효 브랜드 분담률 =\n`MIN(promo_cost_share_ratio, 0.50)` (단, 제4조의 자발적\n차별화 행사 예외 승인 건은 제외)\n3. 최종 브랜드 정산 공제액(납품업자 실부담액) =\n`coupon_discount_krw` ×\n`MIN(promo_cost_share_ratio, 0.50)`\n4. K마켙 최종 부담액 = `coupon_discount_krw` - 최종 브랜드\n정산 공제액 (여기에는 법 제11조제4항에 따라 K마켙이 의무 흡수한 50% 초과분\n`coupon_discount_krw × MAX(0,\npromo_cost_share_ratio - 0.50)`이 포함된다.)'),
  STRUCT('internal_policies/09_kmarket_vendor_promo_settlement/ch02_fifty_percent_cap_settlement_formula/partner_art_004_voluntary_filing_review', 'DOC_09_KMARKET_PARTNER_POLICY', 'internal_policies/09_kmarket_vendor_promo_settlement/ch02_fifty_percent_cap_settlement_formula/partner_art_004_voluntary_filing_review', '제4조', '내규 제4조 — 자발적·차별화 단독 행사(`VOLUNTARY_PROMO_FILING`) 예외 요건 및 상시 캠페인 기각(`REJECTED`) 원칙', 'EXCEPTION_PROVISO', 'users.marketing_opt_in,products.cost_krw,ont_inventory_items.available_stock,ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio', 'campaign_exceptions.voluntary_request_doc_uri,campaign_exceptions.expected_uplift_roi_pct', 'gs://kmarket_okf/okf/internal_policies/09_kmarket_vendor_promo_settlement/ch02_fifty_percent_cap_settlement_formula/partner_art_004_voluntary_filing_review.md', '# 내규 제4조 — 자발적·차별화 단독 행사(`VOLUNTARY_PROMO_FILING`) 예외 요건 및 상시 캠페인 기각(`REJECTED`) 원칙\n\n* **상위 문서 (`Source Document`)**: [K마켙 입점브랜드 공동프로모션 및 쿠폰분담금 정산내규 (제PARTNER-2025-03호)](/internal_policies/09_kmarket_vendor_promo_settlement/doc.md)[^origin_pdf]\n* **출처 페이지**: `09_INTERNAL_K마켙_입점브랜드_공동프로모션_정산내규_2025.pdf` — **2쪽** (`section_number: 제4조`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n제4조(납품업자 자발적·차별화 단독 행사 예외의 엄격한 요건) ① 대규모유통업법\n제11조제5항 단서에 따라 입점브랜드에 50%를 초과하는 판촉비 분담률을 예외적으로\n적용하려면, 캠페인 예외승인 원장(`campaign_exceptions`)에 예외\n유형이 `VOLUNTARY_PROMO_FILING`으로 등재되어 있고 승인 상태가\n`APPROVED`여야 한다.\n② 준법감시실은 입점브랜드가 K마켙의 상시 등급쿠폰·장바구니 리마인드 행사에 단순\n참여한 건에 대하여 브랜드가 50% 초과 분담을 신청하더라도 자발성·차별성 요건\n미충족을 사유로 즉시 기각(`status = \'REJECTED\'`)하여야 하며, 기각된\n건은 제3조제2항에 따라 반드시 50% 상한 캡을 적용하여 정산한다.\n\nK마켙 입점브랜드 공동프로모션 및 쿠폰분담금 정산내규 ― Page 2 / 2'),
  STRUCT('internal_policies/10_kmarket_cs_return_and_logistics_sla/ch01_return_reason_and_shipping_fee/cs_art_001_002_return_reason_rules', 'DOC_10_KMARKET_CS_SLA_POLICY', 'internal_policies/10_kmarket_cs_return_and_logistics_sla/ch01_return_reason_and_shipping_fee/cs_art_001_002_return_reason_rules', '제1조~제2조', '내규 제1조·제2조 — 반품 사유 코드별(`CHANGE_OF_MIND` 7일/6,000원 vs `SIZE_MISMATCH_SPEC_DIFF` 90일/무상 vs `WEAR_AND_WASH_DAMAGE` 거절) 판정 기준', 'INTERNAL_RULE', 'users.marketing_opt_in,products.cost_krw,ont_inventory_items.available_stock,ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio', 'campaign_exceptions.inspection_photo_gcs_uri,order_items.seal_serial_no', 'gs://kmarket_okf/okf/internal_policies/10_kmarket_cs_return_and_logistics_sla/ch01_return_reason_and_shipping_fee/cs_art_001_002_return_reason_rules.md', '# 내규 제1조·제2조 — 반품 사유 코드별(`CHANGE_OF_MIND` 7일/6,000원 vs `SIZE_MISMATCH_SPEC_DIFF` 90일/무상 vs `WEAR_AND_WASH_DAMAGE` 거절) 판정 기준\n\n* **상위 문서 (`Source Document`)**: [K마켙 CS 반품·교환·환불 심사 및 물류 출고지연 SLA 보상내규 (제CX-2025-04호)](/internal_policies/10_kmarket_cs_return_and_logistics_sla/doc.md)[^origin_pdf]\n* **출처 페이지**: `10_INTERNAL_K마켙_CS반품환불_및_물류SLA_보상내규_2025.pdf` — **1쪽** (`section_number: 제1조~제2조`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n제1조(목적) 이 내규는 K마켙에서 발생한 고객 주문(`orders`,\n`order_items`)의 반품·청약철회 심사와 환불 기한 관리, 그리고 국내\n풀필먼트 물류센터의 출고 서비스수준협약(SLA) 위반 시 고객 보상 기준을 명확히 하여\n「전자상거래 등에서의 소비자보호에 관한 법률」을 준수하고 고객 신뢰를 제고함을 목적으로\n한다.\n제2조(반품 사유 코드별 청약철회 가능 기한 및 반품배송비 귀속) ① CS 심사의원 및\n자동화 에이전트는 주문 원장(`orders`)의 배송완료\n시각(`delivered_at`), 반품요청\n시각(`return_requested_at`) 및 주문상품\n원장(`order_items`)의 반품 사유\n코드(`return_reason_code`)를 대조하여 다음과 같이 청약철회 적격성 및\n배송비 부담 주체를 판정한다.\n1. 단순변심(`return_reason_code =\n\'CHANGE_OF_MIND\'`): 전자상거래법 제17조제1항제1호에 따라\n배송완료일(`delivered_at`)로부터 7일 이내에 반품이 요청된 경우 청약철회를\n승인하되, 왕복 반품배송비 6,000원은 고객 부담(환불금액에서 차감 또는 별도\n결제)으로 처리한다. 다만, 외부 착용 흔적·세탁·수선·택(Tag) 파손으로 재판매\n가치가 현저히 감소한 경우(`WEAR_AND_WASH_DAMAGE`)에는 법\n제17조제2항제2호에 따라 청약철회를 거절하고 상품을 고객에게 반송한다.\n2. 표시·광고 내용 상이 또는 실측 사이즈 오기재(`return_reason_code\n= \'SIZE_MISMATCH_SPEC_DIFF\'`): 상품 상세페이지에 표기된 실측\n치수·소재 정보가 실제 배송된 상품과 다른 경우에는 전자상거래법 제17조제1항제2호의\n\'표시·광고 내용과 다르게 이행된 경우\'에 해당하므로, 단순변심 7일 기한이\n경과하였더라도 배송완료일로부터 3개월(90일) 이내(안 날로부터 30일 이내)에는\n청약철회를 무조건 승인하여야 하며, 반품배송비(6,000원)는 K마켙(또는 귀책\n입점브랜드)이 전액 부담(무상반품)한다.\n3. 상품 불량·파손·오배송(`return_reason_code =\n\'DEFECTIVE\'`): 배송완료일로부터 3개월 이내 청약철회를 승인하며,\n반품배송비는 판매자 측이 전액 부담하고 고객에게 사과 포인트 2,000P를 추가\n지급한다.\n\nK마켙 CS 반품·교환·환불 심사 및 물류 출고지연 SLA 보상내규 ― Page 1 / 2'),
  STRUCT('internal_policies/10_kmarket_cs_return_and_logistics_sla/ch02_refund_3days_and_fulfillment_sla/cs_art_003_refund_3days_and_no_customs', 'DOC_10_KMARKET_CS_SLA_POLICY', 'internal_policies/10_kmarket_cs_return_and_logistics_sla/ch02_refund_3days_and_fulfillment_sla/cs_art_003_refund_3days_and_no_customs', '제3조', '내규 제3조 — 입고 후 3영업일 이내 환급(초과 시 연 15% 지연배상금) 및 해외직구 통관고시 적용 금지', 'EXCEPTION_PROVISO', 'users.marketing_opt_in,products.cost_krw,ont_inventory_items.available_stock,ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio', CAST(NULL AS STRING), 'gs://kmarket_okf/okf/internal_policies/10_kmarket_cs_return_and_logistics_sla/ch02_refund_3days_and_fulfillment_sla/cs_art_003_refund_3days_and_no_customs.md', '# 내규 제3조 — 입고 후 3영업일 이내 환급(초과 시 연 15% 지연배상금) 및 해외직구 통관고시 적용 금지\n\n* **상위 문서 (`Source Document`)**: [K마켙 CS 반품·교환·환불 심사 및 물류 출고지연 SLA 보상내규 (제CX-2025-04호)](/internal_policies/10_kmarket_cs_return_and_logistics_sla/doc.md)[^origin_pdf]\n* **출처 페이지**: `10_INTERNAL_K마켙_CS반품환불_및_물류SLA_보상내규_2025.pdf` — **2쪽** (`section_number: 제3조`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n제3조(대금 환급 기한 및 지연배상금 산정) ① 전자상거래법 제18조제2항에 따라 반품\n상품이 물류센터에 회수되어 입고 확인된 날로부터 3영업일 이내에 고객의\n실결제가격(`sale_price_krw`, 유상반품의 경우 반품배송비 6,000원 차감\n후 금액)을 전액 환급하여야 한다.\n② 만약 당사의 귀책으로 인하여 재화 반환일로부터 3영업일을 초과하여 환불이 지연된\n경우에는 초과 일수에 대하여 연 100분의 15(15.0%)의 지연배상금율을 적용한\n지연배상금을 산정하여 환불금과 함께 지급하여야 한다.\n③ 국내 물류센터(김포·용인·양산)에서 출고된 상품의 반품 심사 시에는 관세청 해외직구\n통관고시(14일 반송기한 및 건당 35,000원 국제반송수수료 규정)를 절대\n적용하여서는 아니 된다.'),
  STRUCT('internal_policies/10_kmarket_cs_return_and_logistics_sla/ch02_refund_3days_and_fulfillment_sla/cs_art_004_fulfillment_sla_compensation', 'DOC_10_KMARKET_CS_SLA_POLICY', 'internal_policies/10_kmarket_cs_return_and_logistics_sla/ch02_refund_3days_and_fulfillment_sla/cs_art_004_fulfillment_sla_compensation', '제4조', '내규 제4조 — 물류센터별(`GIMPO-FC` 24h·`YONGIN-FC` 36h·`YANGSAN-FC` 48h) 출고 SLA 위반 시 3,000P 자동 보상', 'EXCEPTION_PROVISO', 'users.marketing_opt_in,products.cost_krw,ont_inventory_items.available_stock,ont_order_items.coupon_discount_krw,brand_vendor_contracts.promo_cost_share_ratio', CAST(NULL AS STRING), 'gs://kmarket_okf/okf/internal_policies/10_kmarket_cs_return_and_logistics_sla/ch02_refund_3days_and_fulfillment_sla/cs_art_004_fulfillment_sla_compensation.md', '# 내규 제4조 — 물류센터별(`GIMPO-FC` 24h·`YONGIN-FC` 36h·`YANGSAN-FC` 48h) 출고 SLA 위반 시 3,000P 자동 보상\n\n* **상위 문서 (`Source Document`)**: [K마켙 CS 반품·교환·환불 심사 및 물류 출고지연 SLA 보상내규 (제CX-2025-04호)](/internal_policies/10_kmarket_cs_return_and_logistics_sla/doc.md)[^origin_pdf]\n* **출처 페이지**: `10_INTERNAL_K마켙_CS반품환불_및_물류SLA_보상내규_2025.pdf` — **2쪽** (`section_number: 제4조`)\n\n## 원문 발췌 (Verbatim Source Text)\n\n제4조(물류센터별 출고 SLA 기준 및 출고지연 자동 보상) ① 풀필먼트운영실은 물류\n원장(`inventory_items`)에 지정된\n물류센터(`distribution_center`)별 표준 출고\n목표시간(`sla_hours`)을 다음과 같이 관리한다.\n1. 김포 자동화 풀필먼트 센터(`GIMPO-FC`): 주문결제\n시각(`orders.created_at`)으로부터 24시간 이내\n출고(`sla_hours = 24`)\n2. 용인 패션 허브 센터(`YONGIN-FC`): 주문결제 시각으로부터 36시간 이내\n출고(`sla_hours = 36`)\n3. 양산 남부권 광역 센터(`YANGSAN-FC`): 주문결제 시각으로부터 48시간\n이내 출고(`sla_hours = 48`)\n② 실제 출고 시각(`orders.shipped_at`)과 주문결제\n시각(`orders.created_at`)의 차이(출고 소요시간)가 해당 상품 출고\n물류센터의 `sla_hours`를 초과한 경우(출고 SLA 위반), 고객의 별도 클레임\n제기가 없더라도 배송완료 즉시 고객에게 \'약속출고 지연 보상 적립금\n3,000포인트(3,000원 상당)\'를 자동 지급한다.\n\nK마켙 CS 반품·교환·환불 심사 및 물류 출고지연 SLA 보상내규 ― Page 2 / 2')
]);

-- [kmarket_ontology.edge_invokes_provision] 부서 맥락(CTX) × 표준 용어(term_key)별 호출 조문 매핑
CREATE OR REPLACE TABLE `YOUR_PROJECT_ID.kmarket_ontology.edge_invokes_provision` AS
SELECT * FROM UNNEST([
  STRUCT('INV_CRM_01' AS edge_id, 'CRM_GROWTH' AS context_id, 'hyper-personalized-reco' AS term_key, 'projects/YOUR_PROJECT_ID/locations/us-central1/glossaries/kmarket-ecommerce-glossary/terms/hyper-personalized-reco' AS glossary_term_uri, 'internal_policies/07_kmarket_crm_hyper_personalization/ch01_cart_abandon_and_optin_gate/crm_art_001_002_cart_abandon_optin' AS provision_slot_id, '장바구니 이탈 실시간 탐지 및 marketing_opt_in=True 필수 검증' AS invocation_reason),
  STRUCT('INV_CRM_02', 'CRM_GROWTH', 'hyper-personalized-reco', 'projects/YOUR_PROJECT_ID/locations/us-central1/glossaries/kmarket-ecommerce-glossary/terms/hyper-personalized-reco', 'internal_policies/07_kmarket_crm_hyper_personalization/ch02_bundle_substitute_and_tier_coupon/crm_art_003_stock_substitute_bundle', '품절 시 대체상품 전환 및 정상재고 시 코디 번들 크로스셀 추천'),
  STRUCT('INV_CRM_03', 'CRM_GROWTH', 'hyper-personalized-reco', 'projects/YOUR_PROJECT_ID/locations/us-central1/glossaries/kmarket-ecommerce-glossary/terms/hyper-personalized-reco', 'internal_policies/07_kmarket_crm_hyper_personalization/ch02_bundle_substitute_and_tier_coupon/crm_art_004_005_tier_coupon_and_night_rule', '회원 등급별 최대 쿠폰 할인율(VVIP/VIP 15%) 및 25% 마진 가드레일 연동'),
  STRUCT('INV_MD_01', 'MD_MERCHANDISING', 'margin-guardrail', 'projects/YOUR_PROJECT_ID/locations/us-central1/glossaries/kmarket-ecommerce-glossary/terms/margin-guardrail', 'internal_policies/08_kmarket_md_margin_and_clearance/ch01_margin_formula_and_25pct_guardrail/md_art_001_002_margin_25pct_guardrail', '실현마진율 산식 및 상시 프로모션 25.0% 최저마진 가드레일 검증'),
  STRUCT('INV_MD_02', 'MD_MERCHANDISING', 'clearance-exception', 'projects/YOUR_PROJECT_ID/locations/us-central1/glossaries/kmarket-ecommerce-glossary/terms/clearance-exception', 'internal_policies/08_kmarket_md_margin_and_clearance/ch02_aged_inventory_clearance_and_exceptions/md_art_003_aged_inventory_10pct_floor', '입고 90일 이상 체화재고 최저마진 10.0% 완화 및 최대 30% 클리어런스 특례'),
  STRUCT('INV_MD_03', 'MD_MERCHANDISING', 'clearance-exception', 'projects/YOUR_PROJECT_ID/locations/us-central1/glossaries/kmarket-ecommerce-glossary/terms/clearance-exception', 'internal_policies/08_kmarket_md_margin_and_clearance/ch02_aged_inventory_clearance_and_exceptions/md_art_004_campaign_exception_override', '캠페인 예외승인 원장(campaign_exceptions) APPROVED 확인 및 마진 완화 적용'),
  STRUCT('INV_PRT_01', 'PARTNER_SETTLEMENT', 'promo-cost-sharing', 'projects/YOUR_PROJECT_ID/locations/us-central1/glossaries/kmarket-ecommerce-glossary/terms/promo-cost-sharing', 'regulations/01_law_large_retail_fair_trade/ch03_promo_cost_sharing_cap/art_011_p3_p5_fifty_percent_cap_and_proviso', '대규모유통업법 제11조제4항 납품업자 판촉비 분담비율 50% 상한 강행규정'),
  STRUCT('INV_PRT_02', 'PARTNER_SETTLEMENT', 'promo-cost-sharing', 'projects/YOUR_PROJECT_ID/locations/us-central1/glossaries/kmarket-ecommerce-glossary/terms/promo-cost-sharing', 'internal_policies/09_kmarket_vendor_promo_settlement/ch02_fifty_percent_cap_settlement_formula/partner_art_003_cap_settlement_formula', '쿠폰 분담금 50% 상한 캡(MIN(promo_cost_share_ratio, 0.50)) 및 초과분 K마켙 흡수 산식'),
  STRUCT('INV_PRT_03', 'PARTNER_SETTLEMENT', 'promo-cost-sharing', 'projects/YOUR_PROJECT_ID/locations/us-central1/glossaries/kmarket-ecommerce-glossary/terms/promo-cost-sharing', 'internal_policies/09_kmarket_vendor_promo_settlement/ch01_prior_agreement_verification/partner_art_001_002_prior_agreement', '공동판촉 사전 서면약정(signed_promo_agreement=True) 검증 및 미약정 시 K마켙 100% 부담'),
  STRUCT('INV_PRT_04', 'PARTNER_SETTLEMENT', 'promo-cost-sharing', 'projects/YOUR_PROJECT_ID/locations/us-central1/glossaries/kmarket-ecommerce-glossary/terms/promo-cost-sharing', 'regulations/01_law_large_retail_fair_trade/ch02_payment_and_return_ban/art_008_payment_deadline', '대규모유통업법 제8조 직매입 60일·특약매입/위수탁 40일 납품대금 지급기한 및 지연이자 연 15.5%'),
  STRUCT('INV_LGL_01', 'LEGAL_COMPLIANCE', 'behavioral-privacy-optin', 'projects/YOUR_PROJECT_ID/locations/us-central1/glossaries/kmarket-ecommerce-glossary/terms/behavioral-privacy-optin', 'regulations/05_pipc_behavioral_targeting_guideline/ch02_optin_and_night_push_ban/pipc_art_003_optin_requirement', '개보위 행태정보 가이드라인 제3조 회원 식별 결합 타겟팅 시 marketing_opt_in=True 필수'),
  STRUCT('INV_LGL_02', 'LEGAL_COMPLIANCE', 'promo-cost-sharing', 'projects/YOUR_PROJECT_ID/locations/us-central1/glossaries/kmarket-ecommerce-glossary/terms/promo-cost-sharing', 'regulations/02_ftc_promo_cost_guideline/sec02_cap_override_and_voluntary_test/guide_05_voluntary_differentiated_test', '공정위 심사지침 Ⅱ.5 법 제11조제5항 단서(자발성·차별성) 엄격 심사 및 상시 캠페인 예외 기각'),
  STRUCT('INV_LGL_03', 'LEGAL_COMPLIANCE', 'hyper-personalized-reco', 'projects/YOUR_PROJECT_ID/locations/us-central1/glossaries/kmarket-ecommerce-glossary/terms/hyper-personalized-reco', 'regulations/04_ftc_dark_pattern_and_reco_guideline/ch01_price_and_stock_truthfulness/dp_art_003_stock_truthfulness', '공정위 다크패턴 가이드라인 제3조 실시간 가용재고 연동 품절 표시 및 대체상품 객관적 안내'),
  STRUCT('INV_CX_01', 'CX_CS_SUPPORT', 'return-withdrawal-eligibility', 'projects/YOUR_PROJECT_ID/locations/us-central1/glossaries/kmarket-ecommerce-glossary/terms/return-withdrawal-eligibility', 'regulations/03_law_ecommerce_consumer_protection/ch02_withdrawal_and_exceptions/ecom_art_017_p1_withdrawal_periods', '전자상거래법 제17조제1항 단순변심 7일 vs 표시·광고 상이 3개월(90일) 청약철회 기한'),
  STRUCT('INV_CX_02', 'CX_CS_SUPPORT', 'return-withdrawal-eligibility', 'projects/YOUR_PROJECT_ID/locations/us-central1/glossaries/kmarket-ecommerce-glossary/terms/return-withdrawal-eligibility', 'internal_policies/10_kmarket_cs_return_and_logistics_sla/ch01_return_reason_and_shipping_fee/cs_art_001_002_return_reason_rules', '반품 사유 코드별 청약철회 적격성 및 왕복배송비(6,000원) 부담 주체 판정'),
  STRUCT('INV_CX_03', 'CX_CS_SUPPORT', 'return-withdrawal-eligibility', 'projects/YOUR_PROJECT_ID/locations/us-central1/glossaries/kmarket-ecommerce-glossary/terms/return-withdrawal-eligibility', 'internal_policies/10_kmarket_cs_return_and_logistics_sla/ch02_refund_3days_and_fulfillment_sla/cs_art_003_refund_3days_and_no_customs', '회수 후 3영업일 이내 대금 환급(초과 시 지연배상금 연 15%) 및 해외직구 통관고시 적용 금지'),
  STRUCT('INV_OPS_01', 'FULFILLMENT_OPS', 'fulfillment-sla-compensation', 'projects/YOUR_PROJECT_ID/locations/us-central1/glossaries/kmarket-ecommerce-glossary/terms/fulfillment-sla-compensation', 'internal_policies/10_kmarket_cs_return_and_logistics_sla/ch02_refund_3days_and_fulfillment_sla/cs_art_004_fulfillment_sla_compensation', '물류센터별 출고 SLA(24h/36h/48h) 위반 시 지연보상 3,000P 자동 지급')
]);

-- [kmarket_ontology.edge_has_exception_proviso] 본칙 ➔ 단서/특례 조문 분기
CREATE OR REPLACE TABLE `YOUR_PROJECT_ID.kmarket_ontology.edge_has_exception_proviso` AS
SELECT * FROM UNNEST([
  STRUCT('PROVISO_MARGIN_CLEARANCE' AS edge_id, 'internal_policies/08_kmarket_md_margin_and_clearance/ch01_margin_formula_and_25pct_guardrail/md_art_001_002_margin_25pct_guardrail' AS base_slot_id, 'internal_policies/08_kmarket_md_margin_and_clearance/ch02_aged_inventory_clearance_and_exceptions/md_art_003_aged_inventory_10pct_floor' AS proviso_slot_id, '입고 후 90일 이상 경과(stock_age_days >= 90) 및 가용재고 30개 이상 체화재고는 최저마진 하한을 25%에서 10%로 완화' AS exception_condition),
  STRUCT('PROVISO_MARGIN_CAMPAIGN_EXC', 'internal_policies/08_kmarket_md_margin_and_clearance/ch01_margin_formula_and_25pct_guardrail/md_art_001_002_margin_25pct_guardrail', 'internal_policies/08_kmarket_md_margin_and_clearance/ch02_aged_inventory_clearance_and_exceptions/md_art_004_campaign_exception_override', '캠페인 예외승인 원장(campaign_exceptions)에 CLEARANCE_OVERRIDE 또는 VIP_RETENTION이 APPROVED된 경우 승인된 마진 하한 적용'),
  STRUCT('PROVISO_PROMO_VOLUNTARY', 'regulations/01_law_large_retail_fair_trade/ch03_promo_cost_sharing_cap/art_011_p3_p5_fifty_percent_cap_and_proviso', 'regulations/02_ftc_promo_cost_guideline/sec02_cap_override_and_voluntary_test/guide_05_voluntary_differentiated_test', '납품업자의 자발적 요청(자발성)과 타 브랜드 대비 차별성이 모두 입증된 단독 행사에 한하여 50% 상한 예외 허용(상시 캠페인 배제)'),
  STRUCT('PROVISO_PARTNER_VOLUNTARY', 'internal_policies/09_kmarket_vendor_promo_settlement/ch02_fifty_percent_cap_settlement_formula/partner_art_003_cap_settlement_formula', 'internal_policies/09_kmarket_vendor_promo_settlement/ch02_fifty_percent_cap_settlement_formula/partner_art_004_voluntary_filing_review', '입점사 자발적·차별화 단독 행사 승인(VENDOR_VOLUNTARY_PROMO, ACTIVE) 시 약정 분담률 허용, 상시 캠페인은 기각(REJECTED)'),
  STRUCT('PROVISO_WITHDRAWAL_RESTRICTION', 'regulations/03_law_ecommerce_consumer_protection/ch02_withdrawal_and_exceptions/ecom_art_017_p1_withdrawal_periods', 'regulations/03_law_ecommerce_consumer_protection/ch02_withdrawal_and_exceptions/ecom_art_017_p2_withdrawal_restrictions', '수령 후 7일 이내라도 소비자 귀책으로 세탁·수선·착용 흔적이 발생하여 가치가 현저히 감소한 경우 청약철회 제한')
]);

-- [kmarket_ontology.edge_delegates_to_internal] 상위 법령 ➔ K마켙 사내내규 위임
CREATE OR REPLACE TABLE `YOUR_PROJECT_ID.kmarket_ontology.edge_delegates_to_internal` AS
SELECT * FROM UNNEST([
  STRUCT('DEL_LAW11_TO_PARTNER03' AS edge_id, 'regulations/01_law_large_retail_fair_trade/ch03_promo_cost_sharing_cap/art_011_p3_p5_fifty_percent_cap_and_proviso' AS external_slot_id, 'internal_policies/09_kmarket_vendor_promo_settlement/ch02_fifty_percent_cap_settlement_formula/partner_art_003_cap_settlement_formula' AS internal_slot_id, '대규모유통업법 제11조제4항 50% 상한 규정을 K마켙 정산 시스템 산식 MIN(promo_cost_share_ratio, 0.50)으로 구체화' AS delegation_scope),
  STRUCT('DEL_PIPC03_TO_CRM02', 'regulations/05_pipc_behavioral_targeting_guideline/ch02_optin_and_night_push_ban/pipc_art_003_optin_requirement', 'internal_policies/07_kmarket_crm_hyper_personalization/ch01_cart_abandon_and_optin_gate/crm_art_001_002_cart_abandon_optin', '개보위 행태정보 가이드라인 제3조 식별 결합 동의 요건을 K마켙 장바구니 리마인드 users.marketing_opt_in=True 게이트로 구체화'),
  STRUCT('DEL_ECOM17_TO_CS02', 'regulations/03_law_ecommerce_consumer_protection/ch02_withdrawal_and_exceptions/ecom_art_017_p1_withdrawal_periods', 'internal_policies/10_kmarket_cs_return_and_logistics_sla/ch01_return_reason_and_shipping_fee/cs_art_001_002_return_reason_rules', '전자상거래법 제17조 청약철회 기한을 K마켙 반품사유 코드(CHANGE_OF_MIND 7일 vs SIZE_MISMATCH_SPEC_DIFF 90일)로 구체화'),
  STRUCT('DEL_DP03_TO_CRM03', 'regulations/04_ftc_dark_pattern_and_reco_guideline/ch01_price_and_stock_truthfulness/dp_art_003_stock_truthfulness', 'internal_policies/07_kmarket_crm_hyper_personalization/ch02_bundle_substitute_and_tier_coupon/crm_art_003_stock_substitute_bundle', '공정위 다크패턴 가이드라인 제3조 실시간 재고·대체상품 안내 원칙을 K마켙 내규 제3조 품절 대체·코디 번들 추천 규칙으로 구체화'),
  STRUCT('DEL_ECOM18_TO_CS03', 'regulations/03_law_ecommerce_consumer_protection/ch03_refund_sla_and_dark_patterns/ecom_art_018_refund_and_return_shipping', 'internal_policies/10_kmarket_cs_return_and_logistics_sla/ch02_refund_3days_and_fulfillment_sla/cs_art_003_refund_3days_and_no_customs', '전자상거래법 제18조 3영업일 환급 및 지연배상금 연 15% 규정을 K마켙 CS 내규 제3조로 구체화')
]);

-- [kmarket_ontology.edge_conflicts_by_sector] 국내 이커머스 규정 vs 해외직구 통관고시 대조군 분리
CREATE OR REPLACE TABLE `YOUR_PROJECT_ID.kmarket_ontology.edge_conflicts_by_sector` AS
SELECT * FROM UNNEST([
  STRUCT('CONF_DOMESTIC_VS_CUSTOMS_01' AS edge_id, 'regulations/03_law_ecommerce_consumer_protection/ch02_withdrawal_and_exceptions/ecom_art_017_p1_withdrawal_periods' AS ecommerce_slot_id, 'distractors/06_distractor_customs_overseas_direct/ch01_overseas_customs_scope/dist_customs_art_003_return_fee' AS distractor_slot_id, '국내 풀필먼트(김포·용인·양산) 출고 주문에는 전자상거래법 제17조(7일/90일, 반품배송비 6,000원)가 적용되며, 관세청 해외직구 특송고시(14일·국제반송수수료 35,000원)를 혼동 적용하면 안 됨' AS conflict_warning),
  STRUCT('CONF_CS_POLICY_VS_CUSTOMS_02', 'internal_policies/10_kmarket_cs_return_and_logistics_sla/ch02_refund_3days_and_fulfillment_sla/cs_art_003_refund_3days_and_no_customs', 'distractors/06_distractor_customs_overseas_direct/ch01_overseas_customs_scope/dist_customs_art_001_002_scope', 'K마켙 국내 물류센터 직매입·특약매입 출고 건에 해외직구 목록통관(미화 150달러) 및 국제반송 규정을 적용 금지')
]);

